std::string join_log_names(const std::vector<std::string>& names) {
    if (names.empty()) return "-";
    std::ostringstream out;
    for (size_t i = 0; i < names.size(); ++i) {
        if (i != 0) out << ",";
        out << names[i];
    }
    return out.str();
}

