void camera_source_first_shot_ok(std::string_view category) {
    // ihatecompvir CameraManager::FindCameraShot sends first_shot_ok(category)
    // once before scanning the category list, but CameraManager::FirstShotOk
    // discards the HandleType return. BandDirector::OnFirstShotOK returns
    // DataNode(0) for non-coop categories and a frame-distance for coop ones,
    // so keep the return class as proof rather than as a selection predicate.
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const bool coop_category = category.rfind("coop_", 0) == 0;
        const char* handler_return =
            coop_category ? "frame_distance" : "DataNode(0)";
        std::fprintf(
            stderr,
            "[world] camera first_shot_ok: source_msg=first_shot_ok source_handler=BandDirector::OnFirstShotOK category=%s coop_category=%d handler_return=%s source_return=discarded result=ignored\n",
            std::string(category).c_str(), coop_category ? 1 : 0,
            handler_return);
    }
}

bool camera_source_banddirector_behind_camera(std::string_view category) {
    static constexpr std::string_view kBehind = "_behind";
    return category.size() > kBehind.size() &&
           category.substr(category.size() - kBehind.size()) == kBehind;
}

bool camera_source_banddirector_facing_camera(std::string_view category) {
    static constexpr std::string_view kCoop = "coop_";
    if (category.size() < kCoop.size()) return false;
    for (size_t i = 0; i < kCoop.size(); ++i) {
        const unsigned char a = static_cast<unsigned char>(category[i]);
        const unsigned char b = static_cast<unsigned char>(kCoop[i]);
        if (std::tolower(a) != std::tolower(b)) return false;
    }
    return !camera_source_banddirector_behind_camera(category);
}

bool camera_source_banddirector_directed_cut(std::string_view category) {
    static constexpr std::string_view kDirected = "directed_";
    return category.size() >= kDirected.size() &&
           category.substr(0, kDirected.size()) == kDirected;
}

bool camera_source_banddirector_bftb(std::string_view category) {
    static constexpr std::string_view kBftb = "BFTB_";
    return category.size() >= kBftb.size() &&
           category.substr(0, kBftb.size()) == kBftb;
}

struct CameraSourceBandDirectorSetShotResult {
    bool writes_shot_category = false;
    bool sets_pick_pending = false;
    bool asserts_bftb = false;
    bool remap_requested = false;
    std::string category;
    const char* reason = "ignored";
};

CameraSourceBandDirectorSetShotResult
camera_source_banddirector_set_shot_like_source(
    std::string_view category,
    std::string_view shot_track,
    bool wardrobe_present,
    bool wardrobe_play_shot5,
    std::string_view wardrobe_play_mode,
    std::string_view remapped_category) {
    CameraSourceBandDirectorSetShotResult result;
    result.category = std::string(category);
    if (!wardrobe_present ||
        camera_source_banddirector_directed_cut(category)) {
        result.reason = "source_gate_false";
        return result;
    }

    result.asserts_bftb = camera_source_banddirector_bftb(category);
    const bool shot5 = shot_track == "shot_5";
    if (shot5 != wardrobe_play_shot5) {
        result.reason = "wardrobe_play_shot5_mismatch";
        return result;
    }
    if (shot5) {
        result.remap_requested = true;
        if (!remapped_category.empty()) {
            result.category = std::string(remapped_category);
        }
    } else if (shot_track != wardrobe_play_mode) {
        result.reason = "wardrobe_play_mode_mismatch";
        return result;
    }

    result.writes_shot_category = true;
    result.sets_pick_pending = true;
    result.reason = shot5 ? "shot_5_remap" : "play_mode_match";
    return result;
}

std::vector<CameraShotSourceFilter> camera_source_banddirector_findnext_filters(
    std::string_view category, const Gameplay::CameraKey* current_shot) {
    std::vector<CameraShotSourceFilter> filters;
    if (!camera_source_banddirector_facing_camera(category)) return filters;
    if (!current_shot ||
        camera_source_banddirector_behind_camera(current_shot->category)) {
        return filters;
    }
    filters.push_back(camera_flags_any_filter((~current_shot->flags) & 0x7000));
    return filters;
}

bool camera_source_category_uses_banddirector_findnext(
    std::string_view category, std::string_view source_message) {
    return !category.empty() &&
           source_message == "BandDirector::FindNextShot";
}

int camera_source_count_bits(int value) {
    int bits = 0;
    const uint32_t source_value = static_cast<uint32_t>(value);
    for (uint32_t bit = 0; bit < 32; ++bit) {
        if (source_value & (uint32_t{1} << bit)) ++bits;
    }
    return bits;
}

int camera_source_banddirector_filter_shot_mask_like_source(
    int mask, std::string_view current_category) {
    if (current_category.find("_behind") != std::string_view::npos) {
        mask |= 0x10;
    } else if ((mask & 0x20) == 0 &&
               current_category.find("_far") != std::string_view::npos) {
        mask |= 0x100;
    }
    return mask;
}

std::string camera_source_banddirector_pickdist_like_source(
    const std::array<float, 4>& weights,
    std::string_view band,
    float distance_random_unit,
    float closeup_random_unit) {
    static constexpr const char* dist_names[] = {"closeup", "near", "far",
                                                 "behind"};
    float total = 0.0f;
    for (float weight : weights) total += weight;
    float unit = distance_random_unit;
    if (!std::isfinite(unit)) unit = 0.0f;
    if (unit < 0.0f) unit = 0.0f;
    if (unit > 1.0f) unit = 1.0f;
    float draw = unit * total;
    int dist = 0;
    for (; dist < 3; ++dist) {
        draw -= weights[dist];
        if (draw < 0.0f) break;
    }

    std::string suffix;
    if (dist == 0 && (band.empty() || band.front() != 'v')) {
        float closeup = closeup_random_unit;
        if (!std::isfinite(closeup)) closeup = 0.0f;
        suffix = closeup > 0.30f ? "_hand" : "_head";
    }
    return std::string(dist_names[dist]) + suffix;
}

std::string camera_source_banddirector_midi_shot_category_like_source(
    int source_mask,
    std::string_view current_category,
    size_t random_fs_index,
    float distance_random_unit,
    float closeup_random_unit) {
    static constexpr int fs[] = {1, 2, 4, 8, 3, 5, 9, 6, 0xA, 0xC, 0xD, 0xF};
    int mask = source_mask;
    int bits = camera_source_count_bits(mask & 0xF);
    if (bits == 3 && (mask & 2)) {
        mask &= ~2;
        bits = 2;
    }
    if (bits == 0) {
        mask |= fs[random_fs_index % 12];
        bits = camera_source_count_bits(mask & 0xF);
    }
    if ((mask & 0x40) && bits != 1) mask &= ~0x40;

    std::array<float, 4> weights = {4.0f, 3.0f, 4.0f, 1.0f};
    mask =
        camera_source_banddirector_filter_shot_mask_like_source(mask,
                                                                current_category);
    if (bits == 4 && (mask & 0x100)) {
        mask &= ~2;
        bits = 3;
    }
    if ((mask & 0x10) || (bits == 2 && (mask & 2))) weights[3] = 0.0f;
    if ((mask & 0x20) || bits == 4) {
        bits = 4;
        mask |= 0x2F;
    } else {
        weights[2] = 0.0f;
    }
    if (bits != 1) mask |= 0x80;
    if (mask & 0x80) weights[0] = 0.0f;
    if (mask & 0x60) weights[1] = 0.0f;

    std::string band;
    if (bits == 4) {
        band = "all";
    } else if (bits == 3) {
        band = "front";
    } else {
        if (mask & 1) band += 'b';
        if (mask & 2) band += 'd';
        if (mask & 4) band += 'g';
        if (mask & 8) band += 'v';
    }
    return "coop_" + band + "_" +
           camera_source_banddirector_pickdist_like_source(
               weights, band, distance_random_unit, closeup_random_unit);
}

void camera_source_no_acceptable_shot(std::string_view category,
                                      CameraShotMode mode,
                                      bool low_excitement,
                                      bool walking,
                                      bool starpower,
                                      size_t normal_category_cursor,
                                      const std::vector<CameraShotSourceFilter>&
                                          source_filters) {
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const std::string source_filter_label =
            camera_source_filter_list_label(source_filters);
        const std::string source_scan_scope =
            camera_source_pick_shot_scan_scope(mode, normal_category_cursor);
        std::fprintf(
            stderr,
            "[world] camera pick_shot warning: source_warn=\"No acceptable camera shot:\" source_warn_cat=%s source_manager=CameraManager::PickCameraShot category=%s category_scan=%s mode=%s filters=\"%s\" filter_count=%zu low_excitement=%d walking=%d starpower=%d result=0\n",
            std::string(category).c_str(), std::string(category).c_str(),
            source_scan_scope.c_str(), camera_shot_mode_label(mode),
            source_filter_label.c_str(), source_filters.size(),
            low_excitement ? 1 : 0, walking ? 1 : 0, starpower ? 1 : 0);
    }
}

std::string camera_category_bucket_order_for_log(
    const std::vector<Gameplay::CameraKey>& keys,
    std::string_view category) {
    std::vector<std::string> names;
    for (const auto& key : keys) {
        if (key.category == category) names.push_back(key.name);
    }
    return join_log_names(names);
}

size_t camera_category_bucket_index(
    const std::vector<Gameplay::CameraKey>& keys,
    std::string_view category,
    size_t key_index) {
    size_t bucket_index = 0;
    for (size_t i = 0; i < key_index && i < keys.size(); ++i) {
        if (keys[i].category == category) ++bucket_index;
    }
    return bucket_index;
}

template <typename Predicate>
std::optional<size_t> choose_regular_camera_key_index_by_category(
    std::vector<Gameplay::CameraKey>& keys,
    const Gameplay::CameraKey* previous,
    CameraShotMode mode,
    std::string_view current_walkspot,
    size_t normal_category_cursor,
    Predicate&& predicate) {
    (void)normal_category_cursor; // GH2 does not round-robin categories.
    ghogx::camera::WeightedSelection pool;
    auto eligible = [&](const Gameplay::CameraKey& key) {
        return key.disabled_flags == 0 && predicate(key) &&
               camera_source_shot_ok(key, previous, current_walkspot);
    };
    if (mode == CameraShotMode::Lighter) {
        pool.append_category(keys, "LIGHTER", eligible);
    } else {
        for (const auto category : kNormalCamShotCategoryOrder)
            pool.append_category(keys, category, eligible);
    }
    const float draw = camera_selection_random().float_range(0.0f, pool.total());
    const auto selected = pool.choose(draw);
    std::fprintf(stderr,
        "[camera-select] route=regular candidates=%zu total=%.6f draw=%.6f selected=%s source=GH2_weighted_used_cycle\n",
        pool.size(), pool.total(), draw, selected ? keys[*selected].name.c_str() : "<none>");
    return selected;
}

template <typename Predicate>
size_t camera_source_camera_shots_prescan_count(
    const std::vector<Gameplay::CameraKey>& keys,
    const Gameplay::CameraKey* previous,
    CameraShotMode mode,
    std::string_view current_walkspot,
    Predicate&& predicate) {
    auto count_category = [&](std::string_view category) {
        size_t count = 0;
        for (const auto& key : keys) {
            if (key.category != category) continue;
            if (key.disabled_flags != 0) continue;
            if (!predicate(key)) continue;
            const CameraSourceShotOkProbe probe =
                camera_source_shot_ok_probe(key, previous, current_walkspot);
            if (!probe.accepted) continue;
            ++count;
        }
        return count;
    };

    if (mode == CameraShotMode::Lighter) {
        return count_category("LIGHTER");
    }
    size_t count = 0;
    for (const auto category : kNormalCamShotCategoryOrder) {
        count += count_category(category);
    }
    return count;
}

const Gameplay::CameraKey* choose_regular_camera_key_scripted(
    std::vector<Gameplay::CameraKey>& keys,
    std::string_view previous_name,
    const Gameplay::CameraKey* source_previous_fallback,
    bool low_excitement,
    bool walking,
    bool starpower,
    CameraShotMode mode,
    int source_faceoff_players,
    std::string_view current_walkspot,
    size_t& normal_category_cursor) {
    if (keys.empty()) return nullptr;
    const size_t category_cursor_before =
        normal_category_cursor % kNormalCamShotCategoryOrder.size();
    const Gameplay::CameraKey* source_previous =
        camera_source_previous_key_for_selection(
            keys, previous_name, source_previous_fallback);
    const bool source_multi_vs = camera_source_gamecfg_mode_multi_vs();
    const std::vector<CameraShotSourceFilter> source_filters =
        camera_source_script_filters(mode, source_previous, low_excitement,
                                     walking, starpower, source_multi_vs,
                                     source_faceoff_players);
    auto source_filter = [&](const Gameplay::CameraKey& key) {
        return camera_category_filter_ok(key, mode) &&
               camera_shot_matches_source_filters(key, source_filters);
    };
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const std::string_view source_category =
            camera_source_pick_shot_category(mode);
        const std::string source_scan_scope =
            camera_source_pick_shot_scan_scope(mode, category_cursor_before);
        const size_t num_shots = camera_source_camera_shots_prescan_count(
            keys, source_previous, mode, current_walkspot, source_filter);
        std::fprintf(
            stderr,
            "[world] camera num_shots: source_msg=diagnostic_prescan source_handle=HANDLE source_handler=CameraManager::OnNumCameraShots category=%s category_scan=%s mode=%s previous=%s count=%zu shot_ok_probe=1 shot_ok_source_call=CamShot::ShotOk source_prev_shot_visible=1 native_prev_shot_visible=0 source_call=CameraManager::NumCameraShots source_return=DataNode(int) source_first_shot_ok=omitted_non_mutating_diagnostic source_mutates_category=0\n",
            std::string(source_category).c_str(),
            source_scan_scope.c_str(), camera_shot_mode_label(mode),
            source_previous ? source_previous->name.c_str() : "",
            num_shots);
    }
    std::optional<size_t> selected =
        choose_regular_camera_key_index_by_category(
            keys, source_previous, mode, current_walkspot,
            category_cursor_before, source_filter);
    if (!selected) {
        camera_source_no_acceptable_shot(camera_source_pick_shot_category(mode),
                                         mode, low_excitement, walking,
                                         starpower, category_cursor_before,
                                         source_filters);
        return nullptr;
    }
    return &keys[*selected];
}

size_t camera_source_category_prescan_count(
    const std::vector<Gameplay::CameraKey>& keys,
    const Gameplay::CameraKey* previous,
    std::string_view category,
    const std::vector<CameraShotSourceFilter>& source_filters,
    std::string_view current_walkspot) {
    size_t count = 0;
    for (const auto& key : keys) {
        if (key.category != category) continue;
        if (key.disabled_flags != 0) continue;
        if (!camera_shot_matches_source_filters(key, source_filters)) continue;
        const CameraSourceShotOkProbe probe =
            camera_source_shot_ok_probe(key, previous, current_walkspot);
        if (!probe.accepted) continue;
        ++count;
    }
    return count;
}

const Gameplay::CameraKey* choose_camera_key_source_category(
    std::vector<Gameplay::CameraKey>& keys,
    std::string_view previous_name,
    const Gameplay::CameraKey* source_previous_fallback,
    std::string_view category,
    std::string_view source_message,
    std::string_view current_walkspot) {
    if (keys.empty() || category.empty()) return nullptr;
    const Gameplay::CameraKey* source_previous =
        camera_source_previous_key_for_selection(
            keys, previous_name, source_previous_fallback);
    const bool source_banddirector_findnext =
        camera_source_category_uses_banddirector_findnext(category,
                                                          source_message);
    const std::vector<CameraShotSourceFilter> source_filters =
        source_banddirector_findnext
            ? camera_source_banddirector_findnext_filters(category,
                                                          source_previous)
            : std::vector<CameraShotSourceFilter>{};
    const char* source_category_caller =
        source_banddirector_findnext ? "BandDirector::FindNextShot"
                                     : "CameraManager::FindCameraShot";
    const std::string source_filter_label =
        camera_source_filter_list_label(source_filters);
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const size_t num_shots = camera_source_category_prescan_count(
            keys, source_previous, category, source_filters, current_walkspot);
        std::fprintf(
            stderr,
            "[world] camera num_shots: source_msg=diagnostic_prescan source_handle=HANDLE source_handler=CameraManager::OnNumCameraShots category=%s mode=source_category previous=%s count=%zu shot_ok_probe=1 shot_ok_source_call=CamShot::ShotOk source_prev_shot_visible=1 native_prev_shot_visible=0 source_call=CameraManager::NumCameraShots source_return=DataNode(int) source_category_caller=%s filters=\"%s\" filter_count=%zu source_first_shot_ok=omitted_non_mutating_diagnostic source_mutates_category=0\n",
            std::string(category).c_str(),
            source_previous ? source_previous->name.c_str() : "",
            num_shots, source_category_caller, source_filter_label.c_str(),
            source_filters.size());
    }
    ghogx::camera::WeightedSelection pool;
    pool.append_category(keys, category, [&](const Gameplay::CameraKey& key) {
        return key.disabled_flags == 0 &&
               camera_shot_matches_source_filters(key, source_filters) &&
               camera_source_shot_ok(key, source_previous, current_walkspot);
    });
    const float draw = camera_selection_random().float_range(0.0f, pool.total());
    const auto selected = pool.choose(draw);
    std::fprintf(stderr,
        "[camera-select] route=category category=%s candidates=%zu total=%.6f draw=%.6f selected=%s source=GH2_weighted_used_cycle\n",
        std::string(category).c_str(), pool.size(), pool.total(), draw,
        selected ? keys[*selected].name.c_str() : "<none>");

    if (!selected) {
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera pick_shot warning: source_warn=\"No acceptable camera shot:\" source_warn_cat=%s source_manager=CameraManager::PickCameraShot source_category_caller=%s category=%s mode=source_category filters=\"%s\" filter_count=%zu source_msg=%s result=0\n",
                std::string(category).c_str(), source_category_caller,
                std::string(category).c_str(), source_filter_label.c_str(),
                source_filters.size(), std::string(source_message).c_str());
        }
        return nullptr;
    }

    return &keys[*selected];
}

uint32_t camera_source_one_bar_to_trigger_tick(
    const ghogx::chart::Chart& chart,
    const ghogx::chart::TextEvent& ev) {
    const uint32_t ticks_per_bar = chart.ticks_per_beat * 4u;
    if (ticks_per_bar == 0 || ev.tick <= ticks_per_bar) return 0;
    return ev.tick - ticks_per_bar;
}

uint32_t camera_source_beat_for_trigger_tick(
    const ghogx::chart::Chart& chart,
    uint32_t trigger_tick) {
    if (chart.ticks_per_beat == 0) return 0;
    return trigger_tick / chart.ticks_per_beat;
}

uint32_t camera_source_one_bar_to_camera_beat_for_trigger(
    const ghogx::chart::Chart& chart,
    uint32_t trigger_tick) {
    // world_objects_worldbase.dta::one_bar_to reads the stored [camera_beat]
    // script variable; seek replay derives the same latch value at the trigger.
    return camera_source_beat_for_trigger_tick(chart, trigger_tick);
}

bool camera_source_one_bar_to_camera_beat_gate_open(
    uint32_t camera_beat) {
    return camera_beat > 0;
}

const char* camera_source_one_bar_to_solo_switch_label(
    std::string_view upcoming_section) {
    if (upcoming_section == "solo") return "solo_true";
    if (upcoming_section == "verse" || upcoming_section == "chorus") {
        return "verse_chorus_false";
    }
    return "default_preserve";
}

bool camera_source_one_bar_to_solo_state_after_section(
    bool current, std::string_view upcoming_section) {
    if (upcoming_section == "solo") return true;
    if (upcoming_section == "verse" || upcoming_section == "chorus") {
        return false;
    }
    return current;
}

size_t camera_source_one_bar_to_cursor_at(const ghogx::chart::Chart& chart,
                                          double song_time) {
    size_t index = 0;
    while (index < chart.text_events.size()) {
        const auto& ev = chart.text_events[index];
        if (!section_venue_event_name(ev.text)) {
            ++index;
            continue;
        }
        const uint32_t trigger_tick =
            camera_source_one_bar_to_trigger_tick(chart, ev);
        if (trigger_tick == 0) {
            ++index;
            continue;
        }
        const double trigger_time = chart.tick_to_sec(trigger_tick);
        if (trigger_time >= song_time) break;
        const uint32_t source_camera_beat =
            camera_source_one_bar_to_camera_beat_for_trigger(chart,
                                                             trigger_tick);
        if (!camera_source_one_bar_to_camera_beat_gate_open(
                source_camera_beat)) {
            ++index;
            continue;
        }
        ++index;
    }
    return index;
}

bool camera_source_one_bar_to_solo_state_at(
    const ghogx::chart::Chart& chart,
    double song_time) {
    bool camera_solo = false;
    for (const auto& ev : chart.text_events) {
        const auto section = section_venue_event_name(ev.text);
        if (!section) continue;
        const uint32_t trigger_tick =
            camera_source_one_bar_to_trigger_tick(chart, ev);
        if (trigger_tick == 0) continue;
        const double trigger_time =
            chart.tick_to_sec(trigger_tick);
        if (trigger_time >= song_time) break;
        const uint32_t source_camera_beat =
            camera_source_one_bar_to_camera_beat_for_trigger(chart,
                                                             trigger_tick);
        if (!camera_source_one_bar_to_camera_beat_gate_open(
                source_camera_beat)) {
            continue;
        }
        camera_solo =
            camera_source_one_bar_to_solo_state_after_section(camera_solo,
                                                              *section);
    }
    return camera_solo;
}

struct CameraSourceLighterSeekState {
    bool did_lighter_cam = false;
    bool lighter_on = false;
    std::string lighter_group;
    size_t events_replayed = 0;
};

CameraSourceLighterSeekState camera_source_lighter_state_at(
    const ghogx::chart::Chart& chart,
    double song_time,
    bool source_multiplayer) {
    CameraSourceLighterSeekState state;
    for (const auto& ev : chart.text_events) {
        if (chart.tick_to_sec(ev.tick) >= song_time) break;
        if (ev.text == "[crowd_lighters_slow]" ||
            ev.text == "[crowd_lighters_fast]") {
            const bool was_off = !state.lighter_on;
            state.lighter_on = true;
            state.lighter_group = ev.text == "[crowd_lighters_slow]"
                                      ? "lighter_slow"
                                      : "lighter_fast";
            if (camera_source_lighter_forces_camera(
                    source_multiplayer, state.did_lighter_cam, was_off)) {
                state.did_lighter_cam = true;
            }
            ++state.events_replayed;
        } else if (ev.text == "[crowd_lighters_off]") {
            state.lighter_on = false;
            state.lighter_group.clear();
            ++state.events_replayed;
        }
    }
    return state;
}

uint32_t camera_bar_at(const ghogx::chart::Chart& chart, double song_time) {
    if (chart.ticks_per_beat == 0) return 0;
    const uint32_t ticks_per_bar = chart.ticks_per_beat * 4u;
    if (ticks_per_bar == 0) return 0;
    return chart.sec_to_tick(song_time) / ticks_per_bar;
}

uint32_t camera_beat_at(const ghogx::chart::Chart& chart, double song_time) {
    if (chart.ticks_per_beat == 0) return 0;
    return chart.sec_to_tick(song_time) / chart.ticks_per_beat;
}

float source_character_task_beat_at(const ghogx::chart::Chart& chart,
                                    double song_time) {
    if (chart.ticks_per_beat == 0) return 0.0f;
    return static_cast<float>(chart.sec_to_tick(std::max(0.0, song_time))) /
           static_cast<float>(chart.ticks_per_beat);
}

int source_random_int_camera_duration_bars(int min_bars, int max_bars,
                                           size_t draw_index) {
    if (min_bars <= 0) min_bars = 1;
    if (max_bars < min_bars) max_bars = min_bars;
    const size_t span = static_cast<size_t>(max_bars - min_bars + 1);
    // world_objects_worldbase.dta::get_shot_duration uses random_int for this
    // source-script route.
    // DataFunc::DataRandomInt calls RandomInt(low, high). That global source
    // Rand starts as gRand(0x29A), and Rand::Int(low, high) treats high as
    // exclusive, so the authored inclusive duration row is submitted as
    // [min, max + 1) here.
    (void)draw_index; // Diagnostic ordinal, not a request to reseed/replay RNG.
    const size_t bucket = camera_selection_random().int_range(span);
    return min_bars + static_cast<int>(bucket);
}

size_t source_random_gh1_face_pose(size_t pose_count, size_t draw_index) {
    if (pose_count == 0) return 0;
    CameraSourceRand rand;
    // GH1 SLUS_212.24 0x287BD0 calls the same global RandomInt path used by
    // DataRandomInt. The retail global Rand starts at 0x29A. Replaying draws
    // from that seed keeps this independent runtime deterministic while
    // preserving the recovered source generator and range semantics.
    rand.seed(0x29Au);
    size_t selected = 0;
    for (size_t i = 0; i <= draw_index; ++i)
        selected = rand.int_range(pose_count);
    return selected;
}

uint32_t source_random_gh1_walk_draw(size_t draw_index) {
    CameraSourceRand rand;
    // GH1 Arena's walk scheduler reaches the same retail global Rand through
    // RandomFloat/RandomInt. Keep a distinct deterministic consumer index so
    // seeks and proof runs reproduce the same walk decisions.
    rand.seed(0x29Au);
    uint32_t value = 0;
    for (size_t i = 0; i <= draw_index; ++i) value = rand.next();
    return value;
}

float source_random_gh1_walk_unit(size_t draw_index) {
    return static_cast<float>(
               static_cast<double>(
                   source_random_gh1_walk_draw(draw_index)) /
               static_cast<double>(
                   std::numeric_limits<uint32_t>::max()));
}

size_t source_random_gh1_walk_index(size_t count, size_t draw_index) {
    if (count == 0) return 0;
    return static_cast<size_t>(
        source_random_gh1_walk_draw(draw_index) %
        static_cast<uint32_t>(count));
}

std::string camera_excitement_duration_key(std::string_view venue_event) {
    switch (venue_excitement_level(venue_event)) {
        case 0:
            return "kExcitementBoot";
        case 1:
            return "kExcitementBad";
        case 3:
            return "kExcitementGreat";
        case 4:
            return "kExcitementPeak";
        case 2:
        default:
            return "kExcitementOkay";
    }
}

std::pair<std::string, std::pair<int, int>> camera_duration_range_for_event(
    const std::map<std::string, std::pair<int, int>>& duration_bars,
    std::string_view venue_event) {
    std::string key = camera_excitement_duration_key(venue_event);
    auto it = duration_bars.find(key);
    if (it != duration_bars.end()) return {key, it->second};
    it = duration_bars.find("kExcitementOkay");
    if (it != duration_bars.end()) return {"kExcitementOkay", it->second};
    return {"kExcitementOkay", {2, 4}};
}

const Gameplay::CameraKey* find_camera_key_by_name(
    const std::vector<Gameplay::CameraKey>& keys, std::string_view name) {
    for (const auto& key : keys) {
        if (key.name == name) return &key;
    }
    return nullptr;
}

float source_camshot_frame_span(const Gameplay::CameraKey& key) {
    if (!key.has_timing || !std::isfinite(key.duration_frames) ||
        !std::isfinite(key.blend_frames) || key.duration_frames < 0.0f ||
        key.blend_frames < 0.0f) {
        return 0.0f;
    }
    return key.duration_frames + key.blend_frames;
}

float source_camshot_frame_total(
    const std::vector<Gameplay::CameraKey>& frames,
    size_t begin = 0) {
    float total = 0.0f;
    for (size_t i = begin; i < frames.size(); ++i) {
        total += source_camshot_frame_span(frames[i]);
    }
    return total;
}

const std::vector<Gameplay::CameraKey>& source_camshot_timing_frames(
    const Gameplay::CameraKey& shot) {
    return !shot.source_camshot_keyframes.empty()
               ? shot.source_camshot_keyframes
               : shot.positions;
}

float source_camshot_duration_frames(const Gameplay::CameraKey& shot) {
    const auto& frames = source_camshot_timing_frames(shot);
    if (!frames.empty()) return source_camshot_frame_total(frames);
    return source_camshot_frame_span(shot);
}

float camera_source_end_frame(const Gameplay::CameraKey& shot) {
    return source_camshot_duration_frames(shot);
}

int camera_source_anim_rate(const Gameplay::CameraKey& shot) {
    return shot.has_camshot_anim_rate ? shot.camshot_anim_rate : 0;
}

float camera_source_frames_per_unit(const Gameplay::CameraKey& shot) {
    return rnd_animatable_frames_per_unit(camera_source_anim_rate(shot));
}

float camera_source_duration_seconds(const Gameplay::CameraKey& shot) {
    if (rnd_animatable_rate_uses_beats(camera_source_anim_rate(shot))) {
        return 0.0f;
    }
    return camera_source_end_frame(shot) / 30.0f;
}

const char* camera_source_duration_seconds_source(
    const Gameplay::CameraKey& shot) {
    return rnd_animatable_rate_uses_beats(camera_source_anim_rate(shot))
               ? "CamShot::GetDurationSeconds(beats_zero)"
               : "CamShot::GetDurationSeconds(seconds_div30)";
}

double camera_source_time_units(const Gameplay::CameraKey& shot,
                                double song_time,
                                double start_time,
                                const ghogx::chart::Chart* chart) {
    const double elapsed = std::max(0.0, song_time - start_time);
    return venue_anim_time_units(camera_source_anim_rate(shot), start_time,
                                 elapsed, chart);
}

float camera_source_local_frame(const Gameplay::CameraKey& shot,
                                double song_time,
                                double start_time,
                                const ghogx::chart::Chart* chart) {
    return static_cast<float>(
        camera_source_time_units(shot, song_time, start_time, chart) *
        static_cast<double>(camera_source_frames_per_unit(shot)));
}

double camera_source_start_time_for_local_frame(
    const Gameplay::CameraKey& shot,
    double song_time,
    double local_frame,
    const ghogx::chart::Chart* chart) {
    const float frames_per_unit = camera_source_frames_per_unit(shot);
    if (!std::isfinite(local_frame) || local_frame <= 0.0 ||
        !std::isfinite(frames_per_unit) || frames_per_unit <= 0.0f) {
        return song_time;
    }
    const int rate = camera_source_anim_rate(shot);
    const double source_units =
        local_frame / static_cast<double>(frames_per_unit);
    const double elapsed_seconds =
        venue_anim_time_units_before_seconds(rate, song_time, source_units, chart);
    return song_time - elapsed_seconds;
}

struct CameraSourceShotOverStatus {
    float local_frame = 0.0f;
    float duration_frames = 0.0f;
    bool mshot_over = false;
    bool looping = false;
    bool duration_valid = false;
    bool local_at_duration = false;
    bool fired = false;
};

CameraSourceShotOverStatus camera_source_shot_over_status(
    const Gameplay::CameraKey& shot,
    double song_time,
    double start_time,
    bool shot_over,
    const ghogx::chart::Chart* chart) {
    CameraSourceShotOverStatus status;
    status.duration_frames = camera_source_end_frame(shot);
    status.local_frame =
        camera_source_local_frame(shot, song_time, start_time, chart);
    status.mshot_over = shot_over;
    status.looping =
        shot.has_camshot_looping ? shot.camshot_looping : true;
    status.duration_valid =
        std::isfinite(status.duration_frames) && status.duration_frames >= 0.0f;
    status.local_at_duration =
        status.duration_valid && status.local_frame >= status.duration_frames;
    status.fired = !status.mshot_over && !status.looping &&
                   status.duration_valid && status.local_at_duration;
    return status;
}

const char* camera_source_shot_over_gate_label(
    const CameraSourceShotOverStatus& status) {
    if (status.mshot_over) return "mShotOver_latched";
    if (status.looping) return "mLooping";
    if (!status.duration_valid) return "invalid_duration";
    if (!status.local_at_duration) return "before_duration";
    return "fire";
}

bool camera_source_check_shot_over(const Gameplay::CameraKey& shot,
                                   double song_time, double start_time,
                                   bool shot_over,
                                   const ghogx::chart::Chart* chart,
                                   float* out_local_frame,
                                   float* out_duration_frames) {
    const CameraSourceShotOverStatus status =
        camera_source_shot_over_status(shot, song_time, start_time, shot_over,
                                       chart);
    if (out_local_frame) *out_local_frame = status.local_frame;
    if (out_duration_frames) *out_duration_frames = status.duration_frames;
    return status.fired;
}

std::vector<Gameplay::CameraKey> regular_camera_source_frame_keys(
    const Gameplay::CameraKey& shot,
    double song_time,
    double start_time,
    const ghogx::chart::Chart* chart) {
    const auto& frames = source_camshot_timing_frames(shot);
    if (frames.empty()) {
        Gameplay::CameraKey null_frame = shot;
        null_frame.source_frame_null_frame = true;
        return {null_frame};
    }

    const float total = source_camshot_frame_total(frames);
    const float raw_local_frame =
        camera_source_local_frame(shot, song_time, start_time, chart);
    float local_frame = raw_local_frame;
    const float now_frame = static_cast<float>(song_time * 30.0);
    size_t loop_start_index = 0;
    float pre_loop = 0.0f;
    float loop_total = 0.0f;
    bool loop_active = false;
    bool loop_wrapped = false;
    auto stamp_source_frame_mapping =
        [&](Gameplay::CameraKey& key, float key_blend, float cursor,
            float duration, float blend, size_t key_index) {
            key.source_frame_local_frame = local_frame;
            key.source_frame_key_start_frame = cursor;
            key.source_frame_duration_frames = duration;
            key.source_frame_blend_frames = blend;
            key.source_frame_key_blend = key_blend;
            key.source_frame_raw_local_frame = raw_local_frame;
            key.source_frame_pre_loop_frames = pre_loop;
            key.source_frame_loop_frames = loop_total;
            key.source_frame_loop_start_index = loop_start_index;
            key.source_frame_key_index = key_index;
            key.source_frame_loop_active = loop_active;
            key.source_frame_loop_wrapped = loop_wrapped;
            key.has_source_frame_key_index = true;
            key.has_source_frame_mapping = true;
        };
    auto make_source_frame_hold =
        [&](const Gameplay::CameraKey& cur, float cursor, float duration,
            float blend, size_t key_index) {
            Gameplay::CameraKey hold = cur;
            hold.frame = now_frame;
            stamp_source_frame_mapping(hold, 0.0f, cursor, duration, blend,
                                       key_index);
            return std::vector<Gameplay::CameraKey>{std::move(hold)};
        };
    auto timing_duration = [](const Gameplay::CameraKey& key) {
        return key.has_timing && std::isfinite(key.duration_frames)
                   ? std::max(0.0f, key.duration_frames)
                   : 0.0f;
    };
    auto timing_blend = [](const Gameplay::CameraKey& key) {
        return key.has_timing && std::isfinite(key.blend_frames)
                   ? std::max(0.0f, key.blend_frames)
                   : 0.0f;
    };
    if (!std::isfinite(total) || total <= 0.001f) {
        const auto& cur = frames.front();
        return make_source_frame_hold(cur, 0.0f, timing_duration(cur),
                                      timing_blend(cur), 0);
    }
    const bool source_looping =
        shot.has_camshot_looping ? shot.camshot_looping : true;
    if (source_looping) {
        loop_start_index = static_cast<size_t>(std::clamp(
            shot.camshot_loop_keyframe, 0,
            static_cast<int>(frames.size() - 1)));
        pre_loop =
            source_camshot_frame_total(frames, 0) -
            source_camshot_frame_total(frames, loop_start_index);
        loop_total = source_camshot_frame_total(frames, loop_start_index);
        if (loop_total > 0.001f && local_frame >= pre_loop) {
            loop_active = true;
            local_frame =
                pre_loop + std::fmod(local_frame - pre_loop, loop_total);
            loop_wrapped =
                std::fabs(local_frame - raw_local_frame) > 0.0001f;
        }
    } else if (local_frame >= total) {
        float cursor = 0.0f;
        for (size_t i = 0; i + 1 < frames.size(); ++i) {
            cursor += source_camshot_frame_span(frames[i]);
        }
        const auto& cur = frames.back();
        return make_source_frame_hold(cur, cursor, timing_duration(cur),
                                      timing_blend(cur), frames.size() - 1);
    }

    float cursor = 0.0f;
    for (size_t i = 0; i < frames.size(); ++i) {
        const auto& cur = frames[i];
        const float duration = timing_duration(cur);
        const float blend = timing_blend(cur);
        const float span = duration + blend;
        if (span <= 0.001f) continue;
        if (local_frame <= cursor + span || i + 1 == frames.size()) {
            const float in_key = std::max(0.0f, local_frame - cursor);
            if (in_key < duration || blend <= 0.001f) {
                return make_source_frame_hold(cur, cursor, duration, blend, i);
            }
            const size_t wrap_index = source_looping ? loop_start_index : i;
            const size_t next_index =
                (i + 1 < frames.size()) ? i + 1 : wrap_index;
            if (next_index == i) {
                return make_source_frame_hold(cur, cursor, duration, blend, i);
            }
            const float t =
                std::clamp((in_key - duration) / blend, 0.0f, 1.0f);
            Gameplay::CameraKey a = cur;
            Gameplay::CameraKey b = frames[next_index];
            a.frame = now_frame - t;
            b.frame = now_frame + (1.0f - t);
            stamp_source_frame_mapping(a, t, cursor, duration, blend, i);
            stamp_source_frame_mapping(b, t, cursor, duration, blend,
                                       next_index);
            return {a, b};
        }
        cursor += span;
    }
    const auto& cur = frames.back();
    cursor = std::max(0.0f, total - source_camshot_frame_span(cur));
    return make_source_frame_hold(cur, cursor, timing_duration(cur),
                                  timing_blend(cur), frames.size() - 1);
}

std::array<float, 2> camshot_result_screen_norm_for_offset(float x, float y) {
    return {(x + 1.0f) * 0.5f, (1.0f - y) * 0.5f};
}

std::array<float, 2> camshot_result_screen_norm_for_key(
    const Gameplay::CameraKey& key) {
    const float x = key.has_screen_offset ? key.screen_offset[0] : 0.0f;
    const float y = key.has_screen_offset ? key.screen_offset[1] : 0.0f;
    return camshot_result_screen_norm_for_offset(x, y);
}

void camera_apply_rndcam_set_frustum_like_source(
    ghogx::render::OrbitCamera& cam, float near_z, float far_z,
    float y_fov, float source_current_far_z, bool emit_debug_row = true) {
    if (!std::isfinite(near_z) || !std::isfinite(far_z) ||
        !std::isfinite(y_fov) || near_z <= 0.0f || far_z <= near_z) {
        return;
    }
    const float requested_near_z = near_z;
    const float requested_far_z = far_z;
    const float requested_y_fov = y_fov;
    bool source_ratio_clamped = false;
    // ihatecompvir RndCam::SetFrustum clamps extreme plane ratios before
    // storing the frustum and rebuilding the local projection transform.
    if (far_z - 0.0001f > near_z * 1000.0f) {
        source_ratio_clamped = true;
        if (far_z == source_current_far_z) near_z = far_z / 1000.0f;
        if (far_z != source_current_far_z) far_z = near_z * 1000.0f;
    }
    cam.near_z = near_z;
    cam.far_z = far_z;
    cam.fov = y_fov;
    if (emit_debug_row &&
        (debug_camera_enabled() || debug_venue_filters_enabled())) {
        std::fprintf(
            stderr,
            "[world] camera SetFrustum: source_class=RndCam requested=(%.3f %.3f %.6f) previous_far=%.3f stored=(%.3f %.3f %.6f) unknown=1.000 ratio_clamped=%d\n",
            requested_near_z, requested_far_z, requested_y_fov,
            source_current_far_z, cam.near_z, cam.far_z, cam.fov,
            source_ratio_clamped ? 1 : 0);
    }
}

struct CameraSourceSetFrustumMessage {
    std::optional<float> near_plane;
    std::optional<float> far_plane;
    std::optional<float> y_fov_degrees;
};

void camera_apply_rndcam_on_set_frustum_like_source(
    ghogx::render::OrbitCamera& cam,
    const CameraSourceSetFrustumMessage& message) {
    constexpr float kDegToRad = 3.14159265358979323846f / 180.0f;
    const float near_z = message.near_plane.value_or(cam.near_z);
    const float far_z = message.far_plane.value_or(cam.far_z);
    const float y_fov =
        message.y_fov_degrees ? (*message.y_fov_degrees * kDegToRad)
                              : cam.fov;
    const float source_current_far_z = cam.far_z;
    camera_apply_rndcam_set_frustum_like_source(
        cam, near_z, far_z, y_fov, source_current_far_z);
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera OnSetFrustum: source_handler=RndCam::OnSetFrustum source_msg=set_frustum has_near=%d has_far=%d has_y_fov=%d requested=(%.3f %.3f %.6f) source_y_fov_units=%s source_return=DataNode(0)\n",
            message.near_plane ? 1 : 0, message.far_plane ? 1 : 0,
            message.y_fov_degrees ? 1 : 0, near_z, far_z, y_fov,
            message.y_fov_degrees ? "degrees_to_radians" : "current_radians");
    }
}

void camera_apply_rndcam_near_plane_prop_like_source(
    ghogx::render::OrbitCamera& cam, float near_plane) {
    const float source_current_far_z = cam.far_z;
    camera_apply_rndcam_set_frustum_like_source(
        cam, near_plane, cam.far_z, cam.fov, source_current_far_z);
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera PropSync: source_class=RndCam prop=near_plane source_expr=SetFrustum(_val,mFarPlane,mYFov,1) requested=%.3f stored=(%.3f %.3f %.6f) source_return=prop_set\n",
            near_plane, cam.near_z, cam.far_z, cam.fov);
    }
}

void camera_apply_rndcam_far_plane_prop_like_source(
    ghogx::render::OrbitCamera& cam, float far_plane) {
    const float source_current_far_z = cam.far_z;
    camera_apply_rndcam_set_frustum_like_source(
        cam, cam.near_z, far_plane, cam.fov, source_current_far_z);
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera PropSync: source_class=RndCam prop=far_plane source_expr=SetFrustum(mNearPlane,_val,mYFov,1) requested=%.3f stored=(%.3f %.3f %.6f) source_return=prop_set\n",
            far_plane, cam.near_z, cam.far_z, cam.fov);
    }
}

void camera_apply_rndcam_y_fov_prop_like_source(
    ghogx::render::OrbitCamera& cam, float y_fov_degrees) {
    constexpr float kDegToRad = 3.14159265358979323846f / 180.0f;
    const float source_current_far_z = cam.far_z;
    camera_apply_rndcam_set_frustum_like_source(
        cam, cam.near_z, cam.far_z, y_fov_degrees * kDegToRad,
        source_current_far_z);
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera PropSync: source_class=RndCam prop=y_fov source_expr=SetFrustum(mNearPlane,mFarPlane,_val*DEG2RAD,1) requested_degrees=%.3f stored=(%.3f %.3f %.6f) source_return=prop_set\n",
            y_fov_degrees, cam.near_z, cam.far_z, cam.fov);
    }
}

float camera_rndcam_on_far_plane_like_source(
    const ghogx::render::OrbitCamera& cam) {
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera far_plane: source_handler=RndCam::OnFarPlane source_return=DataNode(mFarPlane) far_plane=%.3f\n",
            cam.far_z);
    }
    return cam.far_z;
}

void apply_venue_draw_distance_scale(ghogx::render::OrbitCamera& cam) {
    if (!std::isfinite(cam.far_z) || cam.far_z <= 0.0f) return;
    const float expanded_far_z = cam.far_z * kVenueDrawDistanceScale;
    if (std::isfinite(expanded_far_z) && expanded_far_z > cam.near_z) {
        cam.far_z = expanded_far_z;
    }
}

struct ScopedVenueDrawDistance {
    explicit ScopedVenueDrawDistance(ghogx::render::MiloSceneRenderer* world)
        : world(world) {
        if (!world) return;
        original = world->camera();
        apply_venue_draw_distance_scale(world->camera());
        active = true;
    }

    ~ScopedVenueDrawDistance() {
        if (active && world) world->camera() = original;
    }

    ghogx::render::MiloSceneRenderer* world = nullptr;
    ghogx::render::OrbitCamera original;
    bool active = false;
};

