std::string Gameplay::camera_source_guitarist0_nearest_walkspot() const {
    const bool has_gh1_walk_spot =
        gh1_arena_spot_route_active_ &&
        std::any_of(venue_camera_target_worlds_.begin(),
                    venue_camera_target_worlds_.end(),
                    [](const auto& target) {
                        return starts_with(target.first,
                                           "gh1_walk_spot_");
                    });
    if ((!venue_chars_scene_loaded_ ||
         venue_chars_scene_.waypoints.empty()) &&
        !has_gh1_walk_spot) {
        return {};
    }
    const Performer* guitarist0 = nullptr;
    for (const auto& performer : performers_) {
        if (performer.role == "guitarist0") {
            guitarist0 = &performer;
            break;
        }
    }
    if (!guitarist0) return {};

    constexpr uint32_t kWalkSpot = 64u;
    constexpr uint32_t kSoloWalkSpot = 128u;
    const float px = guitarist0->world_transform[12];
    const float py = guitarist0->world_transform[13];
    const float pz = guitarist0->world_transform[14];
    std::string best_name;
    float best_dist2 = std::numeric_limits<float>::max();
    size_t decoded_waypoints = 0;
    size_t candidate_count = 0;

    // GH1 camera.dtb bad_walk_spots indexes Arena::walk_spots.  CharSys's
    // retail get_spot query compares the actor against that vector directly;
    // it never compares the generated GH2 start Waypoint which may occupy the
    // same location.  Prefer the decoded logical vector whenever it exists so
    // a coincident start_guitarist0.way cannot mask an authored rejection.
    if (has_gh1_walk_spot) {
        for (const auto& target : venue_camera_target_worlds_) {
            if (!starts_with(target.first, "gh1_walk_spot_")) continue;
            ++candidate_count;
            const float dx = target.second[12] - px;
            const float dy = target.second[13] - py;
            const float dz = target.second[14] - pz;
            const float dist2 = dx * dx + dy * dy + dz * dz;
            if (best_name.empty() || dist2 < best_dist2) {
                best_name = target.first;
                best_dist2 = dist2;
            }
        }
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera current_walkspot: source_call=CharSys::get_spot source_container=Arena::walk_spots metric=native_world_position_distance2 actor=guitarist0 position=(%.3f %.3f %.3f) result=%s distance2=%.3f candidate_count=%zu\n",
                px, py, pz, best_name.c_str(),
                best_name.empty() ? 0.0f : best_dist2, candidate_count);
        }
        return best_name;
    }

    for (const auto& waypoint : venue_chars_scene_.waypoints) {
        if (!waypoint.decoded) continue;
        ++decoded_waypoints;
        if ((waypoint.flags & (kWalkSpot | kSoloWalkSpot)) == 0) continue;
        ++candidate_count;
        const float dx = waypoint.world_stored.pos[0] - px;
        const float dy = waypoint.world_stored.pos[1] - py;
        const float dz = waypoint.world_stored.pos[2] - pz;
        const float dist2 = dx * dx + dy * dy + dz * dz;
        if (best_name.empty() || dist2 < best_dist2) {
            best_name = waypoint.name;
            best_dist2 = dist2;
        }
    }
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera current_walkspot: source_call=Waypoint::FindNearest source_container=sWaypoints source_iterator=sWaypoints_list_it source_body=rb2_dump_locals_only source_locals=dist,best,it native_container=venue_chars_scene.waypoints metric=native_world_position_distance2 actor=guitarist0 flags=walk|solo_walk mask=0x%08x coordinate=world_stored position=(%.3f %.3f %.3f) result=%s distance2=%.3f waypoints=%zu decoded_waypoints=%zu candidate_count=%zu\n",
            static_cast<unsigned int>(kWalkSpot | kSoloWalkSpot),
            px, py, pz, best_name.c_str(),
            best_name.empty() ? 0.0f : best_dist2,
            venue_chars_scene_.waypoints.size(),
            decoded_waypoints, candidate_count);
    }
    return best_name;
}

const Gameplay::CameraKey* Gameplay::camera_source_intro_previous_key() const {
    return has_source_intro_camera_previous_ ? &source_intro_camera_previous_
                                             : nullptr;
}

bool Gameplay::queue_source_category_camera_shot(
    std::string_view category,
    const char* source_message,
    const CameraKey** queued_key_out) {
    if (queued_key_out) *queued_key_out = nullptr;
    const CameraKey* source_previous_fallback =
        active_regular_camera_.empty() ? camera_source_intro_previous_key()
                                       : nullptr;
    const std::string current_walkspot =
        camera_source_guitarist0_nearest_walkspot();
    const CameraKey* key = choose_camera_key_source_category(
        regular_camera_keys_, active_regular_camera_,
        source_previous_fallback, category,
        source_message && source_message[0] ? source_message : "pick_shot",
        current_walkspot);
    if (!key) {
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera source category pick: source_msg=%s source_action=pick_shot category=%s result=none\n",
                source_message && source_message[0] ? source_message
                                                    : "pick_shot",
                std::string(category).c_str());
        }
        return false;
    }
    queue_regular_camera_shot(*key, "PickCameraShot");
    if (queued_key_out) *queued_key_out = key;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera source category pick: source_msg=%s source_action=pick_shot category=%s shot=%s result=pending\n",
            source_message && source_message[0] ? source_message : "pick_shot",
            std::string(category).c_str(), key->name.c_str());
    }
    return true;
}

bool Gameplay::handle_camera_active_players_changed_like_source(int players) {
    camera_faceoff_active_players_ = std::clamp(players, 0, 2);
    camera_bars_left_ = 4;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera active_players_changed: source_msg=active_players_changed players=%d faceoff_active_players=%d bars_left=%d source_action=pick_new_shot result=pending\n",
            players, camera_faceoff_active_players_, camera_bars_left_);
    }
    return true;
}

std::optional<int> Gameplay::consume_diagnostic_camera_active_players_changed(
    double song_time) {
    if (diagnostic_camera_active_players_change_applied_) return std::nullopt;
    const auto event = camera_diagnostic_active_players_change_event(
        camera_faceoff_active_players_);
    if (!event) return std::nullopt;
    if (song_time + 1e-6 < event->time) return std::nullopt;
    diagnostic_camera_active_players_change_applied_ = true;
    return event->players;
}

void Gameplay::update_source_game_over_camera_messages(
    bool authored_gameplay_cameras_active,
    bool in_intro_camera_window) {
    if (!authored_gameplay_cameras_active || in_intro_camera_window ||
        regular_camera_keys_.empty()) {
        return;
    }

    if (failed_) {
        if (source_game_lost_camera_dispatched_) return;
        source_game_lost_camera_dispatched_ = true;
        camera_bars_left_ = 100;
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera game_lost: source_msg=game_lost source_script=\"set camera_bars_left 100; pick_shot LOSE\" bars_left=%d\n",
                camera_bars_left_);
        }
        queue_source_category_camera_shot("LOSE", "game_lost");
        return;
    }

    if (!chart_loaded_ ||
        song_time_ < std::max(0.0, chart_.duration_sec())) {
        return;
    }

    if (!source_game_won_message_dispatched_) {
        source_game_won_message_dispatched_ = true;
        source_game_won_message_time_ = song_time_;
        const bool source_encore_arg = camera_source_game_won_msg_encore_arg();
        const bool source_win_campaign =
            camera_source_gamecfg_win_campaign_song();
        const bool source_want_encore_fx =
            camera_source_game_want_encore_fx();
        source_game_won_camera_categories_ =
            camera_source_game_won_camera_categories(source_encore_arg,
                                                     source_win_campaign,
                                                     source_want_encore_fx);
        const std::string source_categories =
            join_log_names(source_game_won_camera_categories_);
        camera_bars_left_ = 100;
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera game_won_msg: source_msg=game_won_msg source_script=\"set camera_bars_left 100; script_task delay WIN_CAMERA_DELAY\" categories=%s category_source=%s encore_arg=%d win_campaign_song=%d want_encore_fx=%d delay=%.3f bars_left=%d\n",
                source_categories.c_str(),
                camera_source_game_won_category_source(
                    source_encore_arg, source_win_campaign,
                    source_want_encore_fx),
                source_encore_arg ? 1 : 0, source_win_campaign ? 1 : 0,
                source_want_encore_fx ? 1 : 0, kSourceWinCameraDelaySeconds,
                camera_bars_left_);
        }
    }

    auto dispatch_outro_complete_task = [&]() {
        if (!source_game_won_outro_complete_scheduled_ ||
            source_game_won_outro_complete_dispatched_ ||
            song_time_ + 1e-6 < source_game_won_outro_complete_time_) {
            return;
        }
        source_game_won_outro_complete_dispatched_ = true;
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera game_won_msg set_outro_complete: source_msg=game_won_msg source_task=\"game set_outro_complete\" categories=%s shot=%s elapsed=%.3f scheduled_delay=%.3f duration_source=%s result=dispatched\n",
                join_log_names(source_game_won_camera_categories_).c_str(),
                source_game_won_outro_complete_shot_.c_str(),
                song_time_ - source_game_won_message_time_,
                source_game_won_outro_complete_delay_,
                source_game_won_outro_complete_duration_source_.c_str());
        }
    };

    if (source_game_won_camera_dispatched_) {
        dispatch_outro_complete_task();
        return;
    }
    if (song_time_ + 1e-6 <
        source_game_won_message_time_ + kSourceWinCameraDelaySeconds) {
        return;
    }
    source_game_won_camera_dispatched_ = true;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const std::string source_categories =
            join_log_names(source_game_won_camera_categories_);
        std::fprintf(
            stderr,
            "[world] camera game_won_msg pick: source_msg=game_won_msg source_action=\"pick_shot $category\" categories=%s elapsed=%.3f delay=%.3f\n",
            source_categories.c_str(),
            song_time_ - source_game_won_message_time_,
            kSourceWinCameraDelaySeconds);
    }
    bool queued = false;
    const CameraKey* queued_game_won_key = nullptr;
    for (const auto& category : source_game_won_camera_categories_) {
        if (queue_source_category_camera_shot(category, "game_won_msg",
                                              &queued_game_won_key)) {
            queued = true;
            break;
        }
    }
    const bool outro_complete_branch =
        camera_source_game_won_outro_complete_branch(
            source_game_won_camera_categories_);
    const float outro_delay =
        outro_complete_branch
            ? (queued_game_won_key
                   ? camera_source_duration_seconds(*queued_game_won_key)
                   : 20.0f)
            : 0.0f;
    const char* duration_source =
        !outro_complete_branch
            ? "not_scheduled"
            : (queued_game_won_key
                   ? camera_source_duration_seconds_source(
                         *queued_game_won_key)
                   : "source_fallback_20_seconds");
    if (outro_complete_branch) {
        source_game_won_outro_complete_scheduled_ = true;
        source_game_won_outro_complete_dispatched_ = false;
        source_game_won_outro_complete_time_ = song_time_ + outro_delay;
        source_game_won_outro_complete_delay_ = outro_delay;
        source_game_won_outro_complete_shot_ =
            queued_game_won_key ? queued_game_won_key->name : "";
        source_game_won_outro_complete_duration_source_ = duration_source;
    }
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera game_won_msg outro_complete: source_msg=game_won_msg source_branch=\"category==WIN_ENCORE||category==WIN_GAME\" categories=%s branch=%d shot=%s delay=%.3f duration_source=%s fallback_20s=%d result=%s\n",
            join_log_names(source_game_won_camera_categories_).c_str(),
            outro_complete_branch ? 1 : 0,
            queued_game_won_key ? queued_game_won_key->name.c_str() : "",
            outro_delay, duration_source,
            outro_complete_branch && !queued_game_won_key ? 1 : 0,
            outro_complete_branch ? "schedule_game_set_outro_complete"
                                  : "no_source_task");
    }
    dispatch_outro_complete_task();
    if (!queued && (debug_camera_enabled() || debug_venue_filters_enabled())) {
        std::fprintf(
            stderr,
            "[world] camera game_won_msg pick: source_msg=game_won_msg result=none categories=%s\n",
            join_log_names(source_game_won_camera_categories_).c_str());
    }
}

const Gameplay::CameraKey* Gameplay::camera_manager_source_shot_after(
    const std::string& current_name) const {
    if (regular_camera_keys_.empty()) {
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera ShotAfter: source_expr=shot_after source_handle=HANDLE_EXPR source_manager=CameraManager::ShotAfter current=%s count=0 result=none source_return=DataNode(0)\n",
                current_name.c_str());
        }
        return nullptr;
    }

    std::vector<const CameraKey*> source_ordered;
    source_ordered.reserve(regular_camera_keys_.size());
    for (const auto& key : regular_camera_keys_) {
        source_ordered.push_back(&key);
    }
    std::stable_sort(
        source_ordered.begin(), source_ordered.end(),
        [](const CameraKey* a, const CameraKey* b) {
            return a->source_object_order < b->source_object_order;
        });

    const CameraKey* after = source_ordered.front();
    auto current = std::find_if(
        source_ordered.begin(), source_ordered.end(),
        [&](const CameraKey* key) { return key->name == current_name; });
    const bool current_found = current != source_ordered.end();
    if (current_found) {
        ++current;
        if (current != source_ordered.end()) after = *current;
    }

    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera ShotAfter: source_expr=shot_after source_handle=HANDLE_EXPR source_manager=CameraManager::ShotAfter current=%s current_found=%d first=%s after=%s after_order=%zu object_order=ObjDirItr result=%s source_return=DataNode(CamShot)\n",
            current_name.c_str(), current_found ? 1 : 0,
            source_ordered.front()->name.c_str(), after->name.c_str(),
            after->source_object_order, "shot");
    }
    return after;
}

bool Gameplay::cycle_camera_shot_like_source() {
    const CameraKey* after =
        camera_manager_source_shot_after(active_regular_camera_);
    if (!after) {
        if (debug_camera_enabled() || debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera cycle_shot: source_msg=cycle_shot source_manager=CameraManager::OnCycleShot current=%s result=none source_return=DataNode(0)\n",
                active_regular_camera_.c_str());
        }
        return false;
    }
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera cycle_shot: source_msg=cycle_shot source_manager=CameraManager::OnCycleShot current=%s after=%s source_call=ForceCameraShot result=pending source_return=DataNode(0)\n",
            active_regular_camera_.c_str(), after->name.c_str());
    }
    force_camera_shot_like_source(*after, "CameraManager::OnCycleShot");
    return true;
}

size_t Gameplay::iterate_camera_shots_like_source() const {
    std::vector<const CameraKey*> source_ordered;
    source_ordered.reserve(regular_camera_keys_.size());
    for (const auto& key : regular_camera_keys_) {
        source_ordered.push_back(&key);
    }
    std::stable_sort(source_ordered.begin(), source_ordered.end(),
                     [](const CameraKey* a, const CameraKey* b) {
                         return a->source_object_order < b->source_object_order;
                     });

    std::vector<std::string> categories;
    categories.reserve(source_ordered.size());
    for (const CameraKey* key : source_ordered) {
        if (key->category.empty()) continue;
        if (std::find(categories.begin(), categories.end(), key->category) ==
            categories.end()) {
            categories.push_back(key->category);
        }
    }

    size_t total = 0;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera iterate_shot: source_msg=iterate_shot source_manager=CameraManager::OnIterateShot phase=begin categories=%zu category_order=SyncObjects_ObjDirItr saved_var=1 command_start=3\n",
            categories.size());
    }
    for (const auto& category : categories) {
        size_t category_index = 0;
        for (const CameraKey* key : source_ordered) {
            if (key->category != category) continue;
            if (debug_camera_enabled() || debug_venue_filters_enabled()) {
                std::fprintf(
                    stderr,
                    "[world] camera iterate_shot: source_msg=iterate_shot source_manager=CameraManager::OnIterateShot category=%s category_index=%zu global_index=%zu shot=%s var_write=CamShot command_exec=native_diagnostic_only\n",
                    category.c_str(), category_index, total,
                    key->name.c_str());
            }
            ++category_index;
            ++total;
        }
    }
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera iterate_shot: source_msg=iterate_shot source_manager=CameraManager::OnIterateShot phase=end visited=%zu restore_saved_var=1 result=0\n",
            total);
    }
    return total;
}

bool Gameplay::consume_pending_regular_camera_shot() {
    if (pending_regular_camera_.empty()) return false;
    const double queued_start_preview = pending_regular_camera_start_;
    const double source_local_frame = pending_regular_camera_local_frame_;
    const std::string previous_current = active_regular_camera_;
    const std::string next_shot = pending_regular_camera_;
    const bool shot_changed = previous_current != next_shot;
    const CameraKey* next_key =
        find_camera_key_by_name(regular_camera_keys_, next_shot);
    const double source_start_time =
        next_key ? camera_source_start_time_for_local_frame(
                       *next_key, song_time_, source_local_frame, &chart_)
                 : song_time_;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera PrePoll: source_manager=PrePoll source_field=mNextShot shot=%s previous=%s changed=%d source_start=CameraManager::StartShot_ start_time=%.3f queued_start_preview=%.3f local_frame=%.3f\n",
            next_shot.c_str(), previous_current.c_str(), shot_changed ? 1 : 0,
            source_start_time, queued_start_preview, source_local_frame);
    }
    // CameraManager::PrePoll always calls StartShot_(mNextShot) when mNextShot
    // is set, even if it points to the same CamShot. Preserve that restart so
    // source-local frame timing and StartAnim state reset on repeated picks.
    previous_regular_camera_ = previous_current;
    active_regular_camera_ = next_shot;
    active_regular_camera_start_ = source_start_time;
    active_camera_shot_started_ = false;
    active_camera_shot_started_reported_.clear();
    active_camera_setpreframe_calls_ = 0;
    active_camera_setframe_calls_ = 0;
    active_camera_frame_pair_reported_.clear();
    active_camera_interp_debug_reported_.clear();
    active_camera_last_prev_key_.clear();
    active_camera_last_next_key_.clear();
    active_camera_last_prev_index_ = SIZE_MAX;
    active_camera_last_next_index_ = SIZE_MAX;
    active_camera_last_pair_null_frame_ = false;
    active_camera_shot_over_reported_.clear();
    active_camera_shot_over_gate_reported_.clear();
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const CameraKey* source_current_during_start =
            camera_manager_current_shot_like_source();
        const CameraKey* source_next_during_start =
            camera_manager_next_shot_like_source();
        std::fprintf(
            stderr,
            "[world] camera PrePoll staged: source_manager=PrePoll source_call=StartShot_(mNextShot) source_field=mCurrentShot,mNextShot source_order=before_CamShot_StartAnim_mNextShot_live previous=%s current=%s next_during_start=%s source_current_during_start=%s source_next_during_start=%s local_frame=%.3f start_time=%.3f pipeline_scope=normal_gameplay_camera freecam_priority=deferred_last freecam_affects_gameplay=0\n",
            previous_current.c_str(), active_regular_camera_.c_str(),
            pending_regular_camera_.c_str(),
            source_current_during_start
                ? source_current_during_start->name.c_str()
                : "",
            source_next_during_start ? source_next_during_start->name.c_str()
                                     : "",
            source_local_frame, source_start_time);
    }
    return true;
}

void Gameplay::clear_pending_regular_camera_after_start_like_source() {
    if (pending_regular_camera_.empty()) return;
    const std::string source_next_before_clear = pending_regular_camera_;
    pending_regular_camera_.clear();
    pending_regular_camera_start_ = 0.0;
    pending_regular_camera_local_frame_ = 0.0;
    if (debug_camera_enabled() || debug_venue_filters_enabled()) {
        const CameraKey* source_current_after =
            camera_manager_current_shot_like_source();
        const CameraKey* source_next_after =
            camera_manager_next_shot_like_source();
        std::fprintf(
            stderr,
            "[world] camera PrePoll mNextShot clear: source_manager=PrePoll source_call=mNextShot=0 source_order=after_StartShot_before_SetPreFrame previous=%s current=%s next_before_clear=%s next_after=%s source_current_after=%s source_next_after=%s result=SetPreFrame_ready pipeline_scope=normal_gameplay_camera freecam_priority=deferred_last freecam_affects_gameplay=0\n",
            previous_regular_camera_.c_str(), active_regular_camera_.c_str(),
            source_next_before_clear.c_str(), pending_regular_camera_.c_str(),
            source_current_after ? source_current_after->name.c_str() : "",
            source_next_after ? source_next_after->name.c_str() : "");
    }
}

void Gameplay::start_camera_shot_runtime(const CameraKey& key,
                                         bool source_restart) {
    const std::string runtime_name = camera_runtime_name_for_key(key);
    if (!source_restart && active_camera_runtime_shot_ == runtime_name) return;
    const bool skip_script_crowd_update =
        active_camera_skip_next_crowd_update_;
    end_camera_shot_runtime(skip_script_crowd_update, false);
    if (key.has_gh1_helper) gh1_camera_helper_.begin_shot(key.name);
    active_camera_runtime_shot_ = runtime_name;
    active_camera_native_current_shot_ = runtime_name;
    active_camera_source_current_rndcam_ = "PanelDir::mCam";
    active_camera_shot_started_ = false;
    active_camera_setpreframe_calls_ = 0;
    active_camera_setframe_calls_ = 0;
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera StartAnim: source_msg=start_shot source_order=before_WorldDir_SetCrowds source_field=none_visible native_current_bridge=%s source_rndcam_owner=RndCam::sCurrent source_rndcam_visible_getter=CamShot::GetCam/PanelDir::mCam source_getcam_return=PanelDir::mCam source_rndcam_current=%s source_rndcam_select=not_visible_in_CamShot_StartAnim shot=%s hide_crowd=%d face_camera=%d "
            "force_char_lod=%d ps3_per_pixel=%d hide_list=%zu show_list=%zu gen_hide=%zu "
            "draw_overrides=%zu postproc_overrides=%zu postprocess=%s anims=%zu glow=%s\n",
            active_camera_native_current_shot_.c_str(),
            active_camera_source_current_rndcam_.c_str(),
            active_camera_runtime_shot_.c_str(), key.hide_crowd ? 1 : 0,
            key.crowd_face_camera ? 1 : 0, key.force_char_lod,
            key.ps3_per_pixel ? 1 : 0,
            key.hide_list_refs.size(), key.show_list_refs.size(),
            key.gen_hide_list_refs.size(), key.draw_override_refs.size(),
            key.postproc_override_refs.size(),
            canonical_milo_ref(key.postprocess_ref).c_str(),
            key.camera_anim_refs.size(),
            key.glow_spot_ref.c_str());
        const std::string source_rndcam_ref =
            canonical_milo_ref(active_camera_source_current_rndcam_);
        const auto rndcam_summary_it =
            venue_camera_rndcam_summaries_.find(source_rndcam_ref);
        const bool rndcam_payload_decoded =
            !source_rndcam_ref.empty() &&
            rndcam_summary_it != venue_camera_rndcam_summaries_.end();
        std::fprintf(
            stderr,
            "[world] camera StartAnim RndCam source: source_msg=start_shot source_getcam_return=%s source_payload=%s summaries=%zu %s\n",
            source_rndcam_ref.empty() ? "<none>" : source_rndcam_ref.c_str(),
            rndcam_payload_decoded
                ? "decoded_from_loaded_scene"
                : (source_rndcam_ref == "PanelDir::mCam"
                       ? "paneldir_runtime_current_not_asset_ref"
                       : "not_found_in_loaded_scene"),
            venue_camera_rndcam_summaries_.size(),
            rndcam_payload_decoded
                ? rndcam_summary_it->second.c_str()
                : "source_reader=MiloEditor::RndCam.Read native_reader=milo_scene::decode_cam source_projection=GH2_PS2_RndCam::UpdateLocal_0x001b1f50_recovered");
    }
    active_camera_postprocess_ref_ = canonical_milo_ref(key.postprocess_ref);
    if (debug_venue_filters_enabled() || debug_camera_enabled()) {
        const bool source_selects_postprocess =
            !active_camera_postprocess_ref_.empty();
        std::fprintf(
            stderr,
            "[world] camera start_shot postprocess: source_script=world/camshot.dta source_platform=HX_XBOX source_lifecycle_recovered=RndPostProc::Select/Reset shot=%s postprocess=%s source_call=%s action=%s result=%s active_postprocess=%s postproc_overrides=%zu ps2_runtime_effect=not_applicable_HX_XBOX_only\n",
            active_camera_runtime_shot_.c_str(),
            active_camera_postprocess_ref_.empty()
                ? "<none>"
                : active_camera_postprocess_ref_.c_str(),
            source_selects_postprocess ? "RndPostProc::Select"
                                       : "RndPostProc::Reset",
            source_selects_postprocess ? "postprocess select"
                                       : "rnd reset_postproc",
            source_selects_postprocess ? "selected" : "cleared",
            active_camera_postprocess_ref_.empty()
                ? "<none>"
                : active_camera_postprocess_ref_.c_str(),
            key.postproc_override_refs.size());
        const auto summary_it =
            venue_camera_postprocess_summaries_.find(active_camera_postprocess_ref_);
        const bool source_payload_decoded =
            !active_camera_postprocess_ref_.empty() &&
            summary_it != venue_camera_postprocess_summaries_.end();
        std::fprintf(
            stderr,
            "[world] camera start_shot postprocess_source: source_script=world/camshot.dta source_call=%s shot=%s active_postprocess=%s source_payload=%s summaries=%zu %s\n",
            source_selects_postprocess ? "RndPostProc::Select"
                                       : "RndPostProc::Reset",
            active_camera_runtime_shot_.c_str(),
            active_camera_postprocess_ref_.empty()
                ? "<none>"
                : active_camera_postprocess_ref_.c_str(),
            active_camera_postprocess_ref_.empty()
                ? "reset_no_object"
                : (source_payload_decoded ? "decoded_from_loaded_milo"
                                          : "not_found_in_loaded_milos"),
            venue_camera_postprocess_summaries_.size(),
            source_payload_decoded ? summary_it->second.c_str()
                                   : "source_reader=MiloEditor::RndPostProc.Read render_effect=postprocessor_pipeline_deferred");
    }
    if (key.category == "LOSE" &&
        (debug_venue_filters_enabled() || debug_camera_enabled())) {
        std::fprintf(
            stderr,
            "[world] camera start_shot lose_teleport: source_script=world/camshot.dta source_msg=guitarist0.lose_teleport shot=%s category=%s result=native_deferred\n",
            active_camera_runtime_shot_.c_str(), key.category.c_str());
    }
    active_force_char_lod_ = key.force_char_lod;
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera start_shot set_min_lod: source_msg=world_set_min_lod shot=%s force_char_lod=%d\n",
            active_camera_runtime_shot_.c_str(), active_force_char_lod_);
    }
    const bool source_should_resend_excitement = should_resend_excitement_;
    if (debug_venue_filters_enabled() || debug_camera_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera start_shot resend_excitement: source_msg=world_resend_excitement source_script=world_objects_worldbase.dta::resend_excitement source_call=always handler_gate=should_resend_excitement gate=%d shot=%s event=%s action=%s\n",
            source_should_resend_excitement ? 1 : 0,
            active_camera_runtime_shot_.c_str(), active_venue_event_.c_str(),
            source_should_resend_excitement ? "replay_active_event"
                                            : "clear_latch_only");
    }
    if (source_should_resend_excitement) {
        resend_active_venue_event();
    }
    should_resend_excitement_ = false;
    // GH1 Arena::SwitchCam (0x16FE98) chooses the authored region before the
    // new camera path is polled. Do not reselect during key interpolation.
    if (key.has_gh1_crowd_region && world_) {
        int crowd_region = key.gh1_crowd_region;
        if (const char* diagnostic_region =
                env_value("GHOGX_DIAGNOSTIC_GH1_CROWD_REGION")) {
            crowd_region = std::atoi(diagnostic_region);
            std::fprintf(
                stderr,
                "[world] diagnostic GH1 crowd region override: authored=%d "
                "forced=%d\n",
                key.gh1_crowd_region, crowd_region);
        }
        world_->select_gh1_crowd_region(crowd_region);
    }
    apply_camera_crowd_visibility(key, skip_script_crowd_update);
    const bool has_legacy_source_crowd =
        key.has_crowd_selection || !key.crowd_selection_ref.empty() ||
        !key.crowd_selection_pairs.empty();
    const size_t source_crowd_count =
        !key.crowd_refs.empty()
            ? key.crowd_refs.size()
            : (has_legacy_source_crowd ? 1u : 0u);
    const bool has_source_crowd = source_crowd_count > 0;
    const std::vector<CameraKey::CrowdRef> source_crowd_selections =
        camera_crowd_selections_like_source(key);
    const std::string source_crowd_ref =
        source_crowd_selections.empty() ? std::string()
                                        : source_crowd_selections.front().ref;
    const size_t source_first_crowd_pairs =
        source_crowd_selections.empty()
            ? 0u
            : source_crowd_selections.front().pairs.size();
    const size_t source_total_crowd_pairs =
        camera_crowd_selection_pair_count(source_crowd_selections);
    const std::string source_crowd_modify_stamps =
        camera_crowd_selection_modify_stamps_for_log(source_crowd_selections);
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera StartAnim: source_call=WorldDir::SetCrowds source_order=after_start_shot_before_state_reset shot=%s source_crowds=%zu crowd_select=%d crowd_entries=%zu crowd_ref=%s crowd_pairs=%zu crowd_total_pairs=%zu crowd_modify_stamps=%s source_stamp_source=CamShotCrowd::Load_num source_stamp_compare=WorldCrowd::unk88_unrecovered face_camera=%d script_crowd_update_skipped=%d\n",
            active_camera_runtime_shot_.c_str(),
            source_crowd_count,
            source_crowd_selections.empty() ? 0 : 1,
            source_crowd_selections.size(),
            source_crowd_ref.c_str(),
            source_first_crowd_pairs,
            source_total_crowd_pairs,
            source_crowd_modify_stamps.c_str(),
            key.crowd_face_camera ? 1 : 0,
            skip_script_crowd_update ? 1 : 0);
    }
    camera_result_builder_state_.reset();
    active_camera_shot_over_reported_.clear();
    active_camera_shot_over_gate_reported_.clear();
    if (world_) {
        camera_unset_shake_like_no_current_camshot(world_->camera());
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] camera StartAnim: source_state_reset=CamShot::StartAnim shot=%s source_fields=unk10c,unk110,unkc4,unkdc,unkf4,unkd0,unke8,unk100 scalar_resets=2 vector_resets=6 reset_result_builder=1 shot_over_latch=per_camshot_member reset_shake=1\n",
            active_camera_runtime_shot_.c_str());
        std::fprintf(
            stderr,
            "[world] camera StartAnim handlers: source_handlers=CamShot::OnGetOccluded/CamShot::OnSetAllCrowdChars3D shot=%s get_occluded=%d set_all_to_3D=%d source_return=DataNode(0) submitted_transform=unchanged\n",
            active_camera_runtime_shot_.c_str(),
            camshot_on_get_occluded_like_source(),
            camshot_on_set_all_crowd_chars_3d_like_source());
        std::fprintf(
            stderr,
            "[world] camera StartAnim hide handlers: source_handlers=CamShot::HANDLE_EXPR(gen_hide_list,0)/CamShot::HANDLE_EXPR(clear_hide_list,0) shot=%s gen_hide_list=%d clear_hide_list=%d source_return=DataNode(0) submitted_visibility=unchanged\n",
            active_camera_runtime_shot_.c_str(),
            camshot_gen_hide_list_like_source(),
            camshot_clear_hide_list_like_source());
    }
    if (skip_script_crowd_update) {
        if (debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] camera start_shot crowd_update skipped: source_var=camshot_skip_next_update shot=%s result=cleared\n",
                active_camera_runtime_shot_.c_str());
        }
        active_camera_skip_next_crowd_update_ = false;
    }
    start_camera_shot_anims(key, active_camera_runtime_shot_);
    if (debug_venue_filters_enabled() && has_source_crowd) {
        std::fprintf(
            stderr,
            "[world] camera StartAnim: source_call=CamShotCrowd::Set3DCrowd source_order=after_linked_mAnims shot=%s source_crowds=%zu crowd_select=%d crowd_entries=%zu crowd_ref=%s crowd_pairs=%zu crowd_total_pairs=%zu crowd_modify_stamps=%s source_stamp_source=CamShotCrowd::Load_num source_stamp_compare=WorldCrowd::unk88_unrecovered face_camera=%d\n",
            active_camera_runtime_shot_.c_str(),
            source_crowd_count,
            source_crowd_selections.empty() ? 0 : 1,
            source_crowd_selections.size(),
            source_crowd_ref.c_str(),
            source_first_crowd_pairs,
            source_total_crowd_pairs,
            source_crowd_modify_stamps.c_str(),
            key.crowd_face_camera ? 1 : 0);
    }
    if (source_restart) {
        camera_manager_startshot_side_effects_like_source();
    }
    if (source_restart &&
        (debug_camera_enabled() || debug_venue_filters_enabled())) {
        const CameraKey* source_next_during_start =
            camera_manager_next_shot_like_source();
        std::fprintf(
            stderr,
            "[world] camera StartShot_: source_manager=CameraManager::StartShot_ source_order=after_CamShot_StartAnim shot=%s start_time=%.3f anim_rate=%d task_units=%s fpu=%.1f next_during_start=%s source_next_during_start=%s venue_test=0 source_gate=venue_test!=1 tri_frame_reset=source_WiiRnd_SetTriFrameRendering tri_frame_requested=%d cooldown_reset=source_global_gCooldown cooldown_value=%d native_renderer_side_effect=not_applied\n",
            active_camera_runtime_shot_.c_str(), active_regular_camera_start_,
            camera_source_anim_rate(key),
            rnd_animatable_task_units_label(camera_source_anim_rate(key)),
            camera_source_frames_per_unit(key),
            pending_regular_camera_.c_str(),
            source_next_during_start ? source_next_during_start->name.c_str()
                                     : "",
            camera_manager_tri_frame_requested_ ? 1 : 0,
            camera_manager_source_cooldown_);
    }
    set_camera_glow_spot_ref(key.glow_spot_ref);
}

std::optional<ghogx::render::MiloSceneRenderer::SpotlightState>
Gameplay::camera_glow_spot_state_for_ref(const std::string& raw_ref) const {
    const std::string ref = canonical_milo_ref(raw_ref);
    if (ref.empty()) return std::nullopt;

    for (const auto& spot : lighting_spotlights_) {
        if (canonical_milo_ref(spot.name) != ref) continue;
        ghogx::render::MiloSceneRenderer::SpotlightState out;
        out.name = spot.name;
        out.target_mesh = spot.target;
        if (spot.has_default_state) {
            out.r = spot.default_color[0];
            out.g = spot.default_color[1];
            out.b = spot.default_color[2];
            out.intensity = spot.default_intensity;
        }
        return out;
    }
    return std::nullopt;
}

void Gameplay::set_camera_glow_spot_ref(const std::string& raw_ref) {
    const std::string ref = canonical_milo_ref(raw_ref);
    if (active_camera_glow_spot_ref_ == ref) return;

    active_camera_glow_spot_ref_ = ref;
    active_camera_glow_spot_.reset();
    if (!ref.empty()) {
        active_camera_glow_spot_ = camera_glow_spot_state_for_ref(ref);
    }
    lighting_spot_renderer_dirty_ = true;

    if (debug_venue_filters_enabled()) {
        if (active_camera_glow_spot_) {
            const auto& spot = *active_camera_glow_spot_;
            std::fprintf(
                stderr,
                "[world] camera glow spot active: ref=%s target=%s color=(%.3f %.3f %.3f) intensity=%.3f\n",
                spot.name.c_str(), spot.target_mesh.c_str(), spot.r, spot.g,
                spot.b, spot.intensity);
        } else if (!ref.empty()) {
            std::fprintf(stderr,
                         "[world] camera glow spot unresolved: ref=%s\n",
                         ref.c_str());
        } else {
            std::fprintf(stderr, "[world] camera glow spot cleared\n");
        }
    }

    update_lighting_spotlight_renderer();
}

std::string Gameplay::venue_script_context_state_key(
    const std::string& state_name) const {
    if (venue_script_context_object_.empty()) return state_name;
    return venue_script_context_object_ + "." + state_name;
}

bool Gameplay::apply_venue_script_env_anim(const std::string& anim_name,
                                           float dest_frame,
                                           float period_seconds,
                                           const VenueScriptStep* switch_step) {
    const std::string ref = canonical_milo_ref(anim_name);
    const float clamped_period =
        std::isfinite(period_seconds) ? std::max(0.0f, period_seconds) : 0.0f;

    auto apply_lighting = [&]() -> bool {
        if (!lighting_) return false;
        const auto anim_it = lighting_env_anims_.find(ref);
        if (anim_it == lighting_env_anims_.end()) return false;
        const auto& anim = anim_it->second;
        if (!venue_environment_anim_has_keys(anim)) return false;
        const float target =
            std::clamp(dest_frame, 0.0f, std::max(0.0f, anim.duration_frames));
        const auto current_it =
            lighting_environment_frames_.find(anim.environment);
        const float start =
            current_it == lighting_environment_frames_.end()
                ? 0.0f
                : std::clamp(current_it->second, 0.0f,
                             std::max(0.0f, anim.duration_frames));
        active_lighting_environment_anims_.erase(
            std::remove_if(
                active_lighting_environment_anims_.begin(),
                active_lighting_environment_anims_.end(),
                [&](const ActiveVenueEnvironmentAnim& active) {
                    return active.environment == anim.environment;
                }),
            active_lighting_environment_anims_.end());
        const float initial_frame =
            clamped_period <= 0.0001f ? target : start;
        lighting_environment_frames_[anim.environment] = initial_frame;
        bool color_changed = false;
        bool fog_changed = false;
        sample_environment_anim_tracks(
            anim.environment, anim.color_keys, anim.fog_color_keys,
            anim.fog_range_keys, initial_frame, lighting_environment_colors_,
            lighting_environment_fog_colors_, lighting_environment_fog_ranges_,
            color_changed, fog_changed);
        if (color_changed)
            lighting_->set_environment_color_overrides(
                lighting_environment_colors_);
        if (fog_changed)
            lighting_->set_environment_fog_overrides(
                compose_environment_fog_overrides(
                    lighting_environment_fog_colors_,
                    lighting_environment_fog_ranges_,
                    &lighting_environment_fog_enabled_));
        if (switch_step && switch_step->anim_has_range &&
            std::fabs(switch_step->anim_end_frame -
                      switch_step->anim_start_frame) > 0.0001f) {
            ActiveVenueEnvironmentAnim active;
            active.name = anim.name;
            active.environment = anim.environment;
            active.start_time = song_time_;
            active.duration_frames = anim.duration_frames;
            active.color_keys = anim.color_keys;
            active.fog_color_keys = anim.fog_color_keys;
            active.fog_range_keys = anim.fog_range_keys;
            active.persistent = switch_step->value == 1;
            active.source_blend_period_seconds = clamped_period;
            active.has_source_filter = true;
            active.source_filter.name = "venue_switch_" + ref;
            active.source_filter.target_ref = ref;
            active.source_filter.start_frame = switch_step->anim_start_frame;
            active.source_filter.end_frame = switch_step->anim_end_frame;
            active.source_filter.scale = switch_step->anim_scale;
            if (switch_step->anim_units_explicit) {
                active.source_filter.anim_rate =
                    switch_step->anim_beat_units ? 1 : 0;
                active.source_filter.period = switch_step->anim_period;
            }
            active.source_filter.type = switch_step->value == 1 ? 1 : 0;
            active.duration_seconds = venue_filter_duration_seconds(
                active.source_filter, &chart_, active.start_time);
            active_lighting_environment_anims_.push_back(std::move(active));
        } else if (clamped_period > 0.0001f &&
                   std::fabs(target - start) > 0.0001f) {
            ActiveVenueEnvironmentAnim active;
            active.name = anim.name;
            active.environment = anim.environment;
            active.start_time = song_time_;
            active.duration_seconds = clamped_period;
            active.duration_frames = anim.duration_frames;
            active.start_frame = start;
            active.end_frame = target;
            active.color_keys = anim.color_keys;
            active.fog_color_keys = anim.fog_color_keys;
            active.fog_range_keys = anim.fog_range_keys;
            active.persistent = false;
            active.target_frame_mode = true;
            active_lighting_environment_anims_.push_back(std::move(active));
        }
        std::fprintf(
            stderr,
            "[world] venue script EnvAnim %s -> %s dest=%.2f period=%.3f layer=lighting\n",
            anim.name.c_str(), anim.environment.c_str(), target,
            clamped_period);
        return true;
    };

    auto apply_venue = [&]() -> bool {
        if (!world_) return false;
        const auto anim_it = venue_env_anims_.find(ref);
        if (anim_it == venue_env_anims_.end()) return false;
        const auto& anim = anim_it->second;
        if (!venue_environment_anim_has_keys(anim)) return false;
        const float target =
            std::clamp(dest_frame, 0.0f, std::max(0.0f, anim.duration_frames));
        const auto current_it = venue_environment_frames_.find(anim.environment);
        const float start =
            current_it == venue_environment_frames_.end()
                ? 0.0f
                : std::clamp(current_it->second, 0.0f,
                             std::max(0.0f, anim.duration_frames));
        active_venue_environment_anims_.erase(
            std::remove_if(active_venue_environment_anims_.begin(),
                           active_venue_environment_anims_.end(),
                           [&](const ActiveVenueEnvironmentAnim& active) {
                               return active.environment == anim.environment;
                           }),
            active_venue_environment_anims_.end());
        const float initial_frame =
            clamped_period <= 0.0001f ? target : start;
        venue_environment_frames_[anim.environment] = initial_frame;
        bool color_changed = false;
        bool fog_changed = false;
        sample_environment_anim_tracks(
            anim.environment, anim.color_keys, anim.fog_color_keys,
            anim.fog_range_keys, initial_frame, venue_environment_colors_,
            venue_environment_fog_colors_, venue_environment_fog_ranges_,
            color_changed, fog_changed);
        if (color_changed)
            world_->set_environment_color_overrides(venue_environment_colors_);
        if (fog_changed)
            world_->set_environment_fog_overrides(
                compose_environment_fog_overrides(
                    venue_environment_fog_colors_,
                    venue_environment_fog_ranges_,
                    &venue_environment_fog_enabled_));
        if (switch_step && switch_step->anim_has_range &&
            std::fabs(switch_step->anim_end_frame -
                      switch_step->anim_start_frame) > 0.0001f) {
            ActiveVenueEnvironmentAnim active;
            active.name = anim.name;
            active.environment = anim.environment;
            active.start_time = song_time_;
            active.duration_frames = anim.duration_frames;
            active.color_keys = anim.color_keys;
            active.fog_color_keys = anim.fog_color_keys;
            active.fog_range_keys = anim.fog_range_keys;
            active.persistent = switch_step->value == 1;
            active.source_blend_period_seconds = clamped_period;
            active.has_source_filter = true;
            active.source_filter.name = "venue_switch_" + ref;
            active.source_filter.target_ref = ref;
            active.source_filter.start_frame = switch_step->anim_start_frame;
            active.source_filter.end_frame = switch_step->anim_end_frame;
            active.source_filter.scale = switch_step->anim_scale;
            if (switch_step->anim_units_explicit) {
                active.source_filter.anim_rate =
                    switch_step->anim_beat_units ? 1 : 0;
                active.source_filter.period = switch_step->anim_period;
            }
            active.source_filter.type = switch_step->value == 1 ? 1 : 0;
            active.duration_seconds = venue_filter_duration_seconds(
                active.source_filter, &chart_, active.start_time);
            active_venue_environment_anims_.push_back(std::move(active));
        } else if (clamped_period > 0.0001f &&
                   std::fabs(target - start) > 0.0001f) {
            ActiveVenueEnvironmentAnim active;
            active.name = anim.name;
            active.environment = anim.environment;
            active.start_time = song_time_;
            active.duration_seconds = clamped_period;
            active.duration_frames = anim.duration_frames;
            active.start_frame = start;
            active.end_frame = target;
            active.color_keys = anim.color_keys;
            active.fog_color_keys = anim.fog_color_keys;
            active.fog_range_keys = anim.fog_range_keys;
            active.persistent = false;
            active.target_frame_mode = true;
            active_venue_environment_anims_.push_back(std::move(active));
        }
        std::fprintf(
            stderr,
            "[world] venue script EnvAnim %s -> %s dest=%.2f period=%.3f layer=venue\n",
            anim.name.c_str(), anim.environment.c_str(), target,
            clamped_period);
        return true;
    };

    if (apply_lighting()) return true;
    if (apply_venue()) return true;
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr,
                     "[world] venue script EnvAnim %s unresolved\n",
                     ref.c_str());
    }
    return false;
}

bool Gameplay::apply_venue_script_light_anim(
    const std::string& anim_name, const VenueScriptStep& switch_step) {
    if (!switch_step.anim_has_range) return false;
    const std::string ref = canonical_milo_ref(anim_name);
    auto apply = [&](const auto& anims, auto& active_anims, auto& colors,
                     auto* renderer, const char* layer) -> bool {
        if (!renderer) return false;
        const auto anim_it = anims.find(ref);
        if (anim_it == anims.end() || anim_it->second.color_keys.empty())
            return false;
        const auto& anim = anim_it->second;
        active_anims.erase(
            std::remove_if(active_anims.begin(), active_anims.end(),
                           [&](const ActiveVenueLightAnim& active) {
                               return active.light == anim.light;
                           }),
            active_anims.end());
        VenueAnimFilter filter;
        filter.name = "venue_switch_" + ref;
        filter.target_ref = ref;
        filter.start_frame = switch_step.anim_start_frame;
        filter.end_frame = switch_step.anim_end_frame;
        filter.scale = switch_step.anim_scale;
        if (switch_step.anim_units_explicit) {
            filter.anim_rate = switch_step.anim_beat_units ? 1 : 0;
            filter.period = switch_step.anim_period;
        }
        filter.type = switch_step.value == 1 ? 1 : 0;
        const float initial_frame =
            venue_filter_frame_at(filter, 0.0, false, &chart_, song_time_);
        colors[anim.light] = sample_light_color_key(anim.color_keys,
                                                    initial_frame);
        renderer->set_light_color_overrides(colors);
        if (std::fabs(filter.end_frame - filter.start_frame) > 0.0001f) {
            ActiveVenueLightAnim active;
            active.name = anim.name;
            active.light = anim.light;
            active.start_time = song_time_;
            active.duration_frames = anim.duration_frames;
            active.color_keys = anim.color_keys;
            active.persistent = switch_step.value == 1;
            active.source_blend_period_seconds =
                switch_step.anim_blend_seconds;
            active.has_source_filter = true;
            active.source_filter = filter;
            active.duration_seconds = venue_filter_duration_seconds(
                filter, &chart_, active.start_time);
            active_anims.push_back(std::move(active));
        }
        if (debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] venue script LightAnim %s -> %s frame=%.2f..%.2f type=%s scale=%.3f blend=%.3f layer=%s\n",
                anim.name.c_str(), anim.light.c_str(), filter.start_frame,
                filter.end_frame, filter.type == 1 ? "loop" : "range",
                filter.scale, switch_step.anim_blend_seconds, layer);
        }
        return true;
    };
    if (apply(lighting_light_anims_, active_lighting_light_anims_,
              lighting_light_colors_, lighting_.get(), "lighting")) {
        return true;
    }
    return apply(venue_light_anims_, active_venue_light_anims_,
                 venue_light_colors_, world_.get(), "venue");
}

bool Gameplay::apply_venue_script_animate_to(const VenueScriptStep& step) {
    const std::string ref = canonical_milo_ref(step.name);
    const auto lighting_it = lighting_direct_anim_filters_.find(ref);
    const auto venue_it = venue_direct_anim_filters_.find(ref);
    std::vector<VenueAnimFilter> propagated_filters;
    const std::vector<VenueAnimFilter>* source = nullptr;
    std::vector<ActiveVenueAnimFilter>* active = nullptr;
    const char* scope = nullptr;
    if (lighting_it != lighting_direct_anim_filters_.end()) {
        source = &lighting_it->second;
        active = &active_lighting_anim_filters_;
        scope = "lighting";
    } else if (venue_it != venue_direct_anim_filters_.end()) {
        source = &venue_it->second;
        active = &active_venue_anim_filters_;
        scope = "venue";
    }
    auto collect_view_filters =
        [&](auto&& self, const std::string& raw_ref,
            const auto& groups, const auto& direct,
            std::unordered_set<std::string>& seen) -> void {
        const std::string child_ref = canonical_milo_ref(raw_ref);
        if (!seen.insert(child_ref).second) return;
        if (const auto direct_it = direct.find(child_ref);
            direct_it != direct.end()) {
            propagated_filters.insert(propagated_filters.end(),
                                      direct_it->second.begin(),
                                      direct_it->second.end());
            return;
        }
        const auto group_it = groups.find(child_ref);
        if (group_it == groups.end()) return;
        for (const auto& child : group_it->second)
            self(self, child, groups, direct, seen);
    };
    if (!source) {
        std::unordered_set<std::string> seen;
        collect_view_filters(collect_view_filters, ref,
                             lighting_anim_group_children_,
                             lighting_direct_anim_filters_, seen);
        if (!propagated_filters.empty()) {
            source = &propagated_filters;
            active = &active_lighting_anim_filters_;
            scope = "lighting-view";
        }
    }
    if (!source) {
        propagated_filters.clear();
        std::unordered_set<std::string> seen;
        collect_view_filters(collect_view_filters, ref,
                             venue_anim_group_children_,
                             venue_direct_anim_filters_, seen);
        if (!propagated_filters.empty()) {
            source = &propagated_filters;
            active = &active_venue_anim_filters_;
            scope = "venue-view";
        }
    }
    auto collect_drawable_member_filters =
        [&](const auto& group_meshes, const auto& direct) {
        const auto group_it = group_meshes.find(ref);
        if (group_it == group_meshes.end()) return;
        const std::unordered_set<std::string> members(
            group_it->second.begin(), group_it->second.end());
        for (const auto& [anim_ref, filters] : direct) {
            (void)anim_ref;
            for (const auto& filter : filters) {
                const bool owns_member =
                    std::any_of(filter.targets.begin(), filter.targets.end(),
                                [&](const VenueAnimFilterTarget& target) {
                                    return members.count(target.mesh) != 0;
                                }) ||
                    std::any_of(
                        filter.mesh_anim_targets.begin(),
                        filter.mesh_anim_targets.end(),
                        [&](const VenueAnimFilterMeshTarget& target) {
                            return members.count(target.mesh) != 0;
                        });
                if (owns_member) propagated_filters.push_back(filter);
            }
        }
    };
    if (!source) {
        propagated_filters.clear();
        collect_drawable_member_filters(lighting_group_meshes_,
                                        lighting_direct_anim_filters_);
        if (!propagated_filters.empty()) {
            source = &propagated_filters;
            active = &active_lighting_anim_filters_;
            scope = "lighting-view-members";
        }
    }
    if (!source) {
        propagated_filters.clear();
        collect_drawable_member_filters(venue_group_meshes_,
                                        venue_direct_anim_filters_);
        if (!propagated_filters.empty()) {
            source = &propagated_filters;
            active = &active_venue_anim_filters_;
            scope = "venue-view-members";
        }
    }
    if (!source || !active || source->empty()) {
        if (debug_venue_filters_enabled()) {
            std::fprintf(stderr,
                         "[world] venue script %s unresolved target=%s\n",
                         step.kind == VenueScriptStep::Kind::AnimTask
                             ? "anim_task"
                             : "animate_to",
                         ref.c_str());
        }
        return false;
    }

    const std::string event_name =
        std::string(step.kind == VenueScriptStep::Kind::AnimTask
                        ? "anim_task:"
                        : "animate_to:") +
        ref;
    float start_frame =
        step.anim_has_range ? step.anim_start_frame : 0.0f;
    if (!step.anim_has_range) {
        if (const auto latched = venue_animate_to_frames_.find(ref);
            latched != venue_animate_to_frames_.end()) {
            start_frame = latched->second;
        }
        for (const auto& running : *active) {
            if (running.event_name != event_name ||
                running.filters.empty()) {
                continue;
            }
            const auto& filter = running.filters.front();
            start_frame = venue_filter_frame_at(
                filter, std::max(0.0, song_time_ - running.start_time),
                running.polled, &chart_, running.start_time);
            break;
        }
    }

    const float target = std::max(0.0f, step.anim_dest_frame);
    const float period = std::max(0.0f, step.anim_period);
    std::vector<VenueAnimFilter> filters = *source;
    for (auto& filter : filters) {
        filter.start_frame = start_frame;
        filter.end_frame = target;
        filter.type = 0;
        filter.event_delay_seconds = 0.0f;
        filter.event_blend_seconds = 0.0f;
        filter.offset_frame = 0.0f;
        filter.snap_frame = 0.0f;
        filter.jitter_frame = 0.0f;
        filter.period = 0.0f;
        const float span = std::fabs(target - start_frame);
        const float fpu = rnd_animatable_frames_per_unit(filter.anim_rate);
        filter.scale =
            period > 0.0001f && span > 0.0001f && fpu > 0.0001f
                ? span / (period * fpu)
                : 1.0f;
    }

    ActiveVenueAnimFilter started;
    started.event_name = event_name;
    started.filters = std::move(filters);
    started.start_time = song_time_;
    started.persistent = false;
    start_source_venue_filter_tasks(started, *active);
    active->push_back(std::move(started));
    venue_animate_to_frames_[ref] = target;
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] venue script %s %s frame=%.2f->%.2f period=%.3f scope=%s filters=%zu\n",
            step.kind == VenueScriptStep::Kind::AnimTask ? "anim_task"
                                                         : "animate_to",
            ref.c_str(), start_frame, target, period, scope, source->size());
    }
    return true;
}

bool Gameplay::apply_venue_script_animation(const VenueScriptStep& step) {
    const std::string ref = canonical_milo_ref(step.name);
    const char* operation_name =
        step.kind == VenueScriptStep::Kind::AnimTask
            ? "anim_task"
            : (step.anim_realtime ? "switch_anim_rt" : "switch_anim");
    const auto task_rate = [&](int anim_rate) {
        if (!step.anim_units_explicit) return anim_rate;
        return step.anim_beat_units ? 1 : 0;
    };
    const auto source_scale = [&](int anim_rate) {
        if (step.anim_period <= 0.0001f || !step.anim_has_range) {
            return std::isfinite(step.anim_scale) ? step.anim_scale : 1.0f;
        }
        const float span =
            std::fabs(step.anim_end_frame - step.anim_start_frame);
        const float fpu =
            rnd_animatable_frames_per_unit(task_rate(anim_rate));
        return span > 0.0001f && fpu > 0.0001f
                   ? span / (step.anim_period * fpu)
                   : 1.0f;
    };
    const float blend_seconds =
        step.anim_units_explicit && step.anim_beat_units
            ? static_cast<float>(venue_anim_time_units_to_seconds(
                  1, song_time_, step.anim_blend_seconds, &chart_))
            : step.anim_blend_seconds;
    auto start_particle =
        [&](const std::map<std::string, VenueParticleRoute>& routes,
            std::vector<ActiveVenueParticleSystem>& active_particles,
            const char* particle_scope,
            const std::string& requested_ref) -> bool {
        const auto route_it = routes.find(requested_ref);
        if (route_it == routes.end()) return false;
        VenueParticleRoute route = route_it->second;
        if (route.particle.empty()) {
            if (debug_venue_filters_enabled()) {
                std::fprintf(
                    stderr,
                    "[world] venue animation %s %s resolved source-null ParticleSysAnim no-op scope=%s\n",
                    operation_name,
                    requested_ref.c_str(), particle_scope);
            }
            return true;
        }
        route.has_source_filter = true;
        route.source_filter.name = "venue_switch_" + requested_ref;
        route.source_filter.target_ref = route.anim;
        route.source_filter.start_frame =
            step.anim_has_range ? step.anim_start_frame : 0.0f;
        route.source_filter.end_frame =
            step.anim_has_range ? step.anim_end_frame : route.duration_frames;
        route.source_filter.scale =
            source_scale(route.source_filter.anim_rate);
        if (step.anim_units_explicit) {
            route.source_filter.anim_rate =
                task_rate(route.source_filter.anim_rate);
            route.source_filter.period = step.anim_period;
        }
        route.source_filter.type = step.value == 1 ? 1 : 0;
        route.source_filter.event_blend_seconds = blend_seconds;
        route.source_blend_period_seconds = blend_seconds;

        active_particles.erase(
            std::remove_if(active_particles.begin(), active_particles.end(),
                           [&](const ActiveVenueParticleSystem& active) {
                               return active.particle == route.particle;
                           }),
            active_particles.end());
        ActiveVenueParticleSystem active;
        active.particle = route.particle;
        active.start_time = song_time_;
        active.duration_seconds =
            particle_route_duration_seconds(route, &chart_, song_time_);
        active.duration_frames = route.duration_frames;
        active.source_blend_period_seconds = route.source_blend_period_seconds;
        active.has_source_filter = true;
        active.source_filter = route.source_filter;
        active.start_color_keys = route.start_color_keys;
        active.end_color_keys = route.end_color_keys;
        active.emission_keys = route.emission_keys;
        active.speed_keys = route.speed_keys;
        active.life_keys = route.life_keys;
        active.size_keys = route.size_keys;
        active.persistent = !step.anim_has_range || step.value == 1;
        active_particles.push_back(std::move(active));
        if (debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] venue animation %s %s rate=%d units=%s fpu=%.1f scope=%s particle=%s frame=%.2f..%.2f type=%s scale=%.3f blend=%.3f\n",
                operation_name,
                requested_ref.c_str(), route.source_filter.anim_rate,
                rnd_animatable_task_units_label(
                    route.source_filter.anim_rate),
                rnd_animatable_frames_per_unit(
                    route.source_filter.anim_rate),
                particle_scope, route.particle.c_str(),
                route.source_filter.start_frame, route.source_filter.end_frame,
                step.value == 1 ? "loop" : "range",
                route.source_filter.scale, blend_seconds);
        }
        return true;
    };
    auto start_material =
        [&](const std::map<std::string, VenueMaterialAnim>& anims,
            std::vector<ActiveVenueMaterialAnim>& active_anims,
            std::map<std::string, float>& material_alpha,
            std::map<std::string, std::array<float, 4>>& material_colors,
            std::map<std::string, std::string>& material_textures,
            std::map<std::string,
                     ghogx::render::MiloSceneRenderer::
                         MaterialTexTransformSample>& material_tex_transforms,
            const std::map<std::string, ghogx::milo_scene::MatObj>&
                material_defaults,
            const char* material_scope,
            const std::string& requested_ref) -> bool {
        const auto anim_it = anims.find(requested_ref);
        if (anim_it == anims.end()) return false;
        const auto& anim = anim_it->second;
        const bool has_tex_transform =
            !anim.tex_translation_keys.empty() ||
            !anim.tex_scale_keys.empty() ||
            !anim.tex_rotation_keys.empty();
        const bool has_color = !anim.color_keys.empty();
        const bool has_texture = !anim.texture_keys.empty();
        if (!anim.has_alpha && !has_color && !has_texture &&
            !has_tex_transform) {
            if (debug_venue_filters_enabled()) {
                std::fprintf(
                    stderr,
                    "[world] venue animation %s %s resolved channel-empty MatAnim no-op scope=%s\n",
                    operation_name, requested_ref.c_str(), material_scope);
            }
            return true;
        }

        active_anims.erase(
            std::remove_if(active_anims.begin(), active_anims.end(),
                           [&](const ActiveVenueMaterialAnim& active) {
                               return active.material == anim.material;
                           }),
            active_anims.end());

        ActiveVenueMaterialAnim active;
        active.name = anim.name;
        active.material = anim.material;
        active.has_alpha = anim.has_alpha;
        active.start_alpha =
            anim.has_alpha
                ? current_material_alpha(anim.material, material_alpha,
                                         material_defaults, anim.start_alpha)
                : 1.0f;
        active.end_alpha = anim.end_alpha;
        active.start_time = song_time_;
        active.duration_frames = anim.duration_frames;
        active.color_keys = anim.color_keys;
        active.alpha_keys = anim.alpha_keys;
        active.texture_keys = anim.texture_keys;
        active.tex_translation_keys = anim.tex_translation_keys;
        active.tex_scale_keys = anim.tex_scale_keys;
        active.tex_rotation_keys = anim.tex_rotation_keys;
        active.persistent = !step.anim_has_range || step.value == 1;
        active.source_blend_period_seconds = blend_seconds;
        active.has_source_filter = true;
        active.source_filter.name = "venue_switch_" + requested_ref;
        active.source_filter.target_ref = requested_ref;
        active.source_filter.anim_rate = anim.anim_rate;
        active.source_filter.start_frame =
            step.anim_has_range ? step.anim_start_frame : 0.0f;
        active.source_filter.end_frame =
            step.anim_has_range ? step.anim_end_frame : anim.duration_frames;
        active.source_filter.scale = source_scale(anim.anim_rate);
        if (step.anim_units_explicit) {
            active.source_filter.anim_rate = task_rate(anim.anim_rate);
            active.source_filter.period = step.anim_period;
        }
        active.source_filter.type = step.value == 1 ? 1 : 0;
        active.source_filter.event_blend_seconds = blend_seconds;
        active.duration_seconds = venue_filter_duration_seconds(
            active.source_filter, &chart_, active.start_time);
        if (has_color) {
            active.has_start_color = true;
            active.start_color =
                current_material_color(anim.material, material_colors,
                                       material_defaults);
        }
        if (has_tex_transform) {
            active.has_start_tex_transform = true;
            active.start_tex_transform = current_material_tex_transform(
                anim.material, material_tex_transforms, material_defaults);
        }
        active_anims.push_back(std::move(active));

        if (debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] venue animation %s %s rate=%d units=%s fpu=%.1f scope=%s material=%s frame=%.2f..%.2f type=%s scale=%.3f blend=%.3f\n",
                operation_name,
                requested_ref.c_str(), anim.anim_rate,
                rnd_animatable_task_units_label(anim.anim_rate),
                rnd_animatable_frames_per_unit(anim.anim_rate),
                material_scope, anim.material.c_str(),
                step.anim_has_range ? step.anim_start_frame : 0.0f,
                step.anim_has_range ? step.anim_end_frame
                                    : anim.duration_frames,
                step.value == 1 ? "loop" : "range",
                source_scale(anim.anim_rate),
                blend_seconds);
        }
        (void)material_textures;
        return true;
    };
    if (milo_ref_has_suffix(ref, ".envanim") &&
        apply_venue_script_env_anim(ref, step.anim_start_frame,
                                    blend_seconds, &step)) {
        return true;
    }
    if (milo_ref_has_suffix(ref, ".litanim") &&
        apply_venue_script_light_anim(ref, step)) {
        return true;
    }
    if (start_particle(lighting_direct_particle_anims_,
                       active_lighting_particles_, "lighting", ref) ||
        start_particle(venue_direct_particle_anims_, active_venue_particles_,
                       "venue", ref)) {
        return true;
    }
    if (start_material(lighting_mat_anims_,
                       active_lighting_material_anims_,
                       lighting_material_alpha_, lighting_material_colors_,
                       lighting_material_textures_,
                       lighting_material_tex_transforms_,
                       lighting_material_defaults_, "lighting", ref) ||
        start_material(venue_mat_anims_, active_venue_material_anims_,
                       venue_material_alpha_, venue_material_colors_,
                       venue_material_textures_,
                       venue_material_tex_transforms_,
                       venue_material_defaults_, "venue", ref)) {
        return true;
    }
    const auto lighting_it = lighting_direct_anim_filters_.find(ref);
    const auto venue_it = venue_direct_anim_filters_.find(ref);
    const std::vector<VenueAnimFilter>* source = nullptr;
    std::vector<ActiveVenueAnimFilter>* active = nullptr;
    const char* scope = nullptr;
    if (lighting_it != lighting_direct_anim_filters_.end()) {
        source = &lighting_it->second;
        active = &active_lighting_anim_filters_;
        scope = "lighting";
    } else if (venue_it != venue_direct_anim_filters_.end()) {
        source = &venue_it->second;
        active = &active_venue_anim_filters_;
        scope = "venue";
    }
    if (!source || !active || source->empty()) {
        // RndGroup::SetFrame propagates to the animatable subset built by
        // SyncObjects. Converted GH1 View objects are ordinary GH2 Groups, so
        // this applies to both static OFF states and nondegenerate ranges.
        const auto find_group_children =
            [&](const std::string& child_ref)
                -> const std::vector<std::string>* {
            if (const auto group_it =
                    lighting_anim_group_children_.find(child_ref);
                group_it != lighting_anim_group_children_.end()) {
                return &group_it->second;
            }
            if (const auto group_it =
                    venue_anim_group_children_.find(child_ref);
                group_it != venue_anim_group_children_.end()) {
                return &group_it->second;
            }
            return nullptr;
        };
        if (find_group_children(ref)) {
            std::unordered_set<std::string> seen;
            auto apply_group =
                [&](auto&& self, const std::string& raw_ref) -> bool {
                const std::string child_ref = canonical_milo_ref(raw_ref);
                if (!seen.insert(child_ref).second) return false;
                const std::vector<std::string>* children =
                    find_group_children(child_ref);
                if (!children) {
                    if (start_particle(lighting_direct_particle_anims_,
                                       active_lighting_particles_, "lighting",
                                       child_ref) ||
                        start_particle(venue_direct_particle_anims_,
                                       active_venue_particles_, "venue",
                                       child_ref)) {
                        return true;
                    }
                    if (start_material(lighting_mat_anims_,
                                       active_lighting_material_anims_,
                                       lighting_material_alpha_,
                                       lighting_material_colors_,
                                       lighting_material_textures_,
                                       lighting_material_tex_transforms_,
                                       lighting_material_defaults_, "lighting",
                                       child_ref) ||
                        start_material(venue_mat_anims_,
                                       active_venue_material_anims_,
                                       venue_material_alpha_,
                                       venue_material_colors_,
                                       venue_material_textures_,
                                       venue_material_tex_transforms_,
                                       venue_material_defaults_, "venue",
                                       child_ref)) {
                        return true;
                    }
                    if (milo_ref_has_suffix(child_ref, ".envanim")) {
                        return apply_venue_script_env_anim(
                            child_ref, step.anim_start_frame,
                            blend_seconds, &step);
                    }
                    if (milo_ref_has_suffix(child_ref, ".litanim")) {
                        return apply_venue_script_light_anim(child_ref, step);
                    }
                    VenueScriptStep child_step = step;
                    child_step.name = child_ref;
                    return apply_venue_script_animation(child_step);
                }
                if (children->empty()) {
                    if (debug_venue_filters_enabled()) {
                        std::fprintf(
                            stderr,
                            "[world] venue animation %s %s resolved empty RndGroup no-op\n",
                            operation_name,
                            child_ref.c_str());
                    }
                    return true;
                }
                bool applied = false;
                for (const auto& child : *children) {
                    applied = self(self, child) || applied;
                }
                return applied;
            };
            if (apply_group(apply_group, ref)) return true;
        }
        if (debug_venue_filters_enabled()) {
            std::fprintf(
                stderr,
                "[world] venue animation %s unresolved target=%s range=%d frame=%.2f..%.2f type=%s scale=%.3f blend=%.3f\n",
                operation_name,
                ref.c_str(), step.anim_has_range ? 1 : 0,
                step.anim_start_frame, step.anim_end_frame,
                step.value == 1 ? "loop" : "range", step.anim_scale,
                blend_seconds);
        }
        return false;
    }

    std::vector<VenueAnimFilter> filters = *source;
    for (auto& filter : filters) {
        if (step.anim_has_range) {
            filter.start_frame = step.anim_start_frame;
            filter.end_frame = step.anim_end_frame;
            filter.type = step.value == 1 ? 1 : 0;
        }
        filter.scale = source_scale(filter.anim_rate);
        if (step.anim_units_explicit) {
            filter.anim_rate = task_rate(filter.anim_rate);
            filter.period = step.anim_period;
        }
        filter.event_blend_seconds = blend_seconds;
        filter.event_delay_seconds = 0.0f;
    }
    const float resolved_scale =
        filters.empty() ? source_scale(0) : filters.front().scale;
    ActiveVenueAnimFilter started;
    started.event_name = "venue_switch_anim:" + ref;
    started.filters = std::move(filters);
    started.start_time = song_time_;
    started.persistent = !step.anim_has_range || step.value == 1;
    start_source_venue_filter_tasks(started, *active);
    active->push_back(std::move(started));
    if (debug_venue_filters_enabled()) {
        const int source_rate =
            source->empty() ? 0 : source->front().anim_rate;
        std::fprintf(
            stderr,
            "[world] venue animation %s %s rate=%d units=%s fpu=%.1f scope=%s frame=%.2f..%.2f type=%s scale=%.3f blend=%.3f filters=%zu\n",
            operation_name,
            ref.c_str(), source_rate,
            rnd_animatable_task_units_label(source_rate),
            rnd_animatable_frames_per_unit(source_rate), scope,
            step.anim_start_frame, step.anim_end_frame,
            step.value == 1 ? "loop" : "range", resolved_scale,
            blend_seconds, source->size());
    }
    return true;
}

bool Gameplay::set_legacy_venue_object_showing(
    const std::string& object_name, bool showing) {
    const std::string ref = canonical_milo_ref(object_name);
    auto apply = [&](const auto& groups, const auto& mesh_positions,
                     auto& hidden, auto* renderer) -> bool {
        std::vector<std::string> meshes;
        if (const auto group_it = groups.find(ref); group_it != groups.end()) {
            meshes = group_it->second;
        } else if (mesh_positions.find(ref) != mesh_positions.end()) {
            meshes.push_back(ref);
        }
        if (meshes.empty()) return false;
        for (const auto& mesh : meshes) {
            if (showing)
                hidden.erase(mesh);
            else
                hidden.insert(mesh);
        }
        if (renderer) {
            if (&hidden == &lighting_runtime_hidden_meshes_)
                renderer->set_hidden_meshes(composed_lighting_hidden_meshes());
            else
                renderer->set_hidden_meshes(composed_venue_hidden_meshes());
        }
        return true;
    };
    bool applied = apply(lighting_group_meshes_,
                         lighting_mesh_source_local_positions_,
                         lighting_runtime_hidden_meshes_, lighting_.get());
    if (!applied) {
        applied = apply(venue_group_meshes_, venue_mesh_source_local_positions_,
                        venue_runtime_hidden_meshes_, world_.get());
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr,
                     "[world] legacy set_showing %s=%d resolved=%d\n",
                     ref.c_str(), showing ? 1 : 0, applied ? 1 : 0);
    }
    return applied;
}

bool Gameplay::venue_proxy_camera_fully_hidden(
    const std::string& object_name,
    const VenueProxyObject& proxy) const {
    const auto hidden_it =
        venue_camera_hidden_proxy_meshes_.find(object_name);
    if (hidden_it == venue_camera_hidden_proxy_meshes_.end() ||
        proxy.all_meshes.empty()) {
        return false;
    }
    const auto shown_it = venue_camera_shown_proxy_meshes_.find(object_name);
    for (const auto& mesh : proxy.all_meshes) {
        if (shown_it != venue_camera_shown_proxy_meshes_.end() &&
            shown_it->second.find(mesh) != shown_it->second.end()) {
            return false;
        }
        if (hidden_it->second.find(mesh) == hidden_it->second.end()) {
            return false;
        }
    }
    return true;
}

void Gameplay::set_venue_proxy_object_showing(const std::string& object_name,
                                              bool showing) {
    auto proxy_it = venue_proxy_objects_.find(object_name);
    if (proxy_it == venue_proxy_objects_.end()) return;
    auto& proxy = proxy_it->second;
    proxy.showing = showing;
    if (!proxy.renderer) return;
    std::unordered_set<std::string> hidden_meshes;
    if (!showing) {
        hidden_meshes.insert(proxy.all_meshes.begin(), proxy.all_meshes.end());
    } else if (const auto hidden_it =
                   venue_camera_hidden_proxy_meshes_.find(object_name);
               hidden_it != venue_camera_hidden_proxy_meshes_.end()) {
        hidden_meshes = hidden_it->second;
    }
    if (const auto shown_it =
            venue_camera_shown_proxy_meshes_.find(object_name);
        shown_it != venue_camera_shown_proxy_meshes_.end()) {
        for (const auto& mesh : shown_it->second) hidden_meshes.erase(mesh);
    }
    proxy.renderer->set_hidden_meshes(std::move(hidden_meshes));
    if (!showing) {
        proxy.renderer->set_active_particle_systems({});
        proxy.renderer->set_particle_intensities({});
        proxy.renderer->set_particle_sizes({});
        proxy.renderer->set_particle_speeds({});
        proxy.renderer->set_particle_lifetimes({});
        proxy.renderer->set_particle_start_colors({});
        proxy.renderer->set_particle_end_colors({});
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr, "[world] RndDir proxy %s showing=%d\n",
                     object_name.c_str(), showing ? 1 : 0);
    }
}

void Gameplay::start_venue_proxy_object_animation(
    const std::string& object_name, float start_frame, float end_frame,
    float period_seconds) {
    auto proxy_it = venue_proxy_objects_.find(object_name);
    if (proxy_it == venue_proxy_objects_.end()) return;
    auto& proxy = proxy_it->second;
    float authored_end = proxy.directory_anim.end_frame;
    for (const auto& [name, anim] : proxy.mat_anims) {
        (void)name;
        authored_end = std::max(authored_end, anim.duration_frames);
    }
    for (const auto& route : proxy.particle_routes)
        authored_end = std::max(authored_end, route.duration_frames);
    if (!std::isfinite(start_frame) || start_frame < 0.0f) start_frame = 0.0f;
    if (!std::isfinite(end_frame) || end_frame <= start_frame)
        end_frame = authored_end > start_frame ? authored_end : start_frame + 1.0f;
    proxy.animating = true;
    proxy.anim_start_time = song_time_;
    proxy.anim_start_frame = start_frame;
    proxy.anim_end_frame = end_frame;
    proxy.anim_period = std::max(0.0f, period_seconds);
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] RndDir proxy %s animate %.2f..%.2f period=%.3f authored_end=%.2f\n",
            object_name.c_str(), proxy.anim_start_frame, proxy.anim_end_frame,
            proxy.anim_period, authored_end);
    }
}

void Gameplay::stop_venue_proxy_object_animation(
    const std::string& object_name) {
    auto proxy_it = venue_proxy_objects_.find(object_name);
    if (proxy_it == venue_proxy_objects_.end()) return;
    auto& proxy = proxy_it->second;
    proxy.animating = false;
    if (proxy.renderer) {
        proxy.renderer->set_mesh_transform_offsets({});
        proxy.renderer->set_mesh_position_overrides({});
        proxy.renderer->set_mesh_normal_overrides({});
        proxy.renderer->set_mesh_texcoord_overrides({});
        proxy.renderer->set_mesh_color_overrides({});
        proxy.renderer->set_mesh_anim_blends({});
        proxy.renderer->set_material_alpha_multipliers({});
        proxy.renderer->set_material_color_overrides({});
        proxy.renderer->set_material_texture_overrides({});
        proxy.renderer->set_material_tex_transform_overrides({});
        proxy.renderer->set_active_particle_systems({});
        proxy.renderer->set_particle_intensities({});
        proxy.renderer->set_particle_sizes({});
        proxy.renderer->set_particle_speeds({});
        proxy.renderer->set_particle_lifetimes({});
        proxy.renderer->set_particle_start_colors({});
        proxy.renderer->set_particle_end_colors({});
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr, "[world] RndDir proxy %s stop_animation\n",
                     object_name.c_str());
    }
}

bool Gameplay::execute_venue_proxy_object_message(
    const VenueScriptObjectMessage& message) {
    auto proxy_it = venue_proxy_objects_.find(message.object);
    if (proxy_it == venue_proxy_objects_.end()) return false;
    if (message.message == "stop") {
        set_venue_proxy_object_showing(message.object, false);
        stop_venue_proxy_object_animation(message.object);
        return true;
    }
    if (message.message == "start" || message.message == "throw" ||
        message.message == "venue_effect") {
        set_venue_proxy_object_showing(message.object, true);
        start_venue_proxy_object_animation(
            message.object, 0.0f, proxy_it->second.directory_anim.end_frame,
            0.0f);
        return true;
    }
    return false;
}

bool Gameplay::execute_venue_script_object_message(
    const VenueScriptObjectMessage& message) {
    const auto object_it = venue_script_objects_.find(message.object);
    if (object_it == venue_script_objects_.end()) return false;
    const auto handlers_it =
        venue_script_object_handlers_.find(object_it->second.type);
    if (handlers_it == venue_script_object_handlers_.end())
        return execute_venue_proxy_object_message(message);
    const auto handler_it = handlers_it->second.find(message.message);
    if (handler_it == handlers_it->second.end())
        return execute_venue_proxy_object_message(message);

    const std::string prev_object = venue_script_context_object_;
    const std::string prev_type = venue_script_context_type_;
    const bool prev_executing = executing_venue_script_;
    venue_script_context_object_ = message.object;
    venue_script_context_type_ = object_it->second.type;
    executing_venue_script_ = true;
    std::vector<std::string> stack;
    stack.push_back(message.object + "." + message.message);
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr,
                     "[world] venue script object %s type=%s message=%s\n",
                     message.object.c_str(), object_it->second.type.c_str(),
                     message.message.c_str());
    }
    execute_venue_script_steps(handler_it->second.steps, stack);
    venue_script_context_object_ = prev_object;
    venue_script_context_type_ = prev_type;
    executing_venue_script_ = prev_executing;
    return true;
}

bool Gameplay::execute_venue_script_object_messages(
    const std::map<std::string, std::vector<VenueScriptObjectMessage>>& routes,
    const std::string& event_name) {
    const auto route_it = routes.find(event_name);
    if (route_it == routes.end()) return false;
    bool applied = false;
    for (const auto& message : route_it->second) {
        applied = execute_venue_script_object_message(message) || applied;
    }
    return applied;
}

std::string Gameplay::evaluate_venue_script_expression(
    const VenueScriptExpression& expression) {
    const auto truthy = [](const std::string& value) {
        return !value.empty() && value != "0" && value != "0.000000" &&
               value != "FALSE" && value != "kDataUnhandled";
    };
    const auto child = [&](size_t index) {
        return index < expression.children.size()
                   ? evaluate_venue_script_expression(
                         expression.children[index])
                   : std::string{};
    };
    if (expression.children.empty()) return expression.atom;
    if (expression.atom.empty()) return child(0);
    if (expression.atom == "not")
        return truthy(child(0)) ? "0" : "1";
    if (expression.atom == "&&") {
        for (size_t i = 0; i < expression.children.size(); ++i) {
            if (!truthy(child(i))) return "0";
        }
        return "1";
    }
    if (expression.atom == "||") {
        for (size_t i = 0; i < expression.children.size(); ++i) {
            if (truthy(child(i))) return "1";
        }
        return "0";
    }
    if (expression.atom == "==" || expression.atom == "!=") {
        const bool equal = child(0) == child(1);
        return (expression.atom == "==" ? equal : !equal) ? "1" : "0";
    }
    if (expression.atom == ">") {
        try {
            return std::stod(child(0)) > std::stod(child(1)) ? "1" : "0";
        } catch (const std::exception&) {
            return "0";
        }
    }
    if (expression.atom == "random_int") {
        try {
            const int minimum =
                static_cast<int>(std::floor(std::stod(child(0))));
            const int maximum =
                static_cast<int>(std::floor(std::stod(child(1))));
            const int low = std::min(minimum, maximum);
            const int high = std::max(minimum, maximum);
            const int value = static_cast<int>(std::floor(
                venue_script_random_float(
                    static_cast<double>(low),
                    static_cast<double>(high) + 1.0)));
            return std::to_string(std::clamp(value, low, high));
        } catch (const std::exception&) {
            return "0";
        }
    }
    if (expression.atom == "arena" && child(0) == "cam_msg") {
        if (!active_regular_camera_.empty()) return active_regular_camera_;
        if (!pending_regular_camera_.empty()) return pending_regular_camera_;
        return source_intro_camera_previous_.name;
    }
    if (expression.atom == "arena" &&
        child(0) == "camshot_category_flags") {
        const std::string requested = child(1);
        const std::string active =
            !active_regular_camera_.empty() ? active_regular_camera_
                                            : pending_regular_camera_;
        for (const auto& camera : regular_camera_keys_) {
            if (camera.name != active) continue;
            return camera.category == requested ? "1" : "0";
        }
        return "0";
    }
    const auto object = venue_script_objects_.find(expression.atom);
    if (object != venue_script_objects_.end()) {
        const auto property = object->second.properties.find(child(0));
        if (property != object->second.properties.end())
            return property->second;
    }
    return "0";
}

bool Gameplay::set_namespaced_performer_object_showing(
    const std::string& role, const std::string& object_name, bool showing) {
    bool applied = false;
    for (auto& performer : performers_) {
        if (performer.role != role || !performer.renderer) continue;
        applied =
            performer.renderer->set_object_showing(object_name, showing) ||
            applied;
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] GH1 with_namespace role=%s object=%s showing=%d resolved=%d source=ObjectDir::Current\n",
            role.c_str(), object_name.c_str(), showing ? 1 : 0,
            applied ? 1 : 0);
    }
    return applied;
}

void Gameplay::execute_venue_script_steps(
    const std::vector<VenueScriptStep>& steps, std::vector<std::string>& stack,
    const std::map<std::string, std::vector<std::string>>* variables) {
    const auto resolve_argument =
        [&](const VenueScriptStep::Argument& argument) {
            if (argument.switch_expression && variables) {
                const auto selector = variables->find(argument.selector);
                if (selector != variables->end() &&
                    !selector->second.empty()) {
                    try {
                        const int key = std::stoi(selector->second.front());
                        const auto value = argument.switch_values.find(key);
                        if (value != argument.switch_values.end())
                            return value->second;
                    } catch (const std::exception&) {
                    }
                }
                return std::vector<std::string>{};
            }
            if (argument.variable && variables && !argument.values.empty()) {
                const auto it = variables->find(argument.values.front());
                if (it != variables->end()) return it->second;
            }
            return argument.values;
        };
    for (const auto& step : steps) {
        switch (step.kind) {
            case VenueScriptStep::Kind::SetState:
                venue_script_state_[venue_script_context_state_key(step.name)] =
                    step.value;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script set %s=%d\n",
                                 venue_script_context_state_key(step.name).c_str(),
                                 step.value);
                }
                break;
            case VenueScriptStep::Kind::CallHandler: {
                const VenueScriptHandler* handler = nullptr;
                std::string handler_key = step.name;
                if (!venue_script_context_type_.empty()) {
                    const auto type_it = venue_script_object_handlers_.find(
                        venue_script_context_type_);
                    if (type_it != venue_script_object_handlers_.end()) {
                        const auto object_handler =
                            type_it->second.find(step.name);
                        if (object_handler != type_it->second.end()) {
                            handler = &object_handler->second;
                            handler_key = venue_script_context_type_ + "::" +
                                          step.name;
                        }
                    }
                }
                if (!handler) {
                    const auto function_it =
                        venue_script_functions_.find(step.name);
                    if (function_it != venue_script_functions_.end()) {
                        handler = &function_it->second;
                        handler_key = "func::" + step.name;
                    }
                }
                if (!handler) {
                    const auto handler_it =
                        venue_script_handlers_.find(step.name);
                    if (handler_it != venue_script_handlers_.end())
                        handler = &handler_it->second;
                }
                if (std::find(stack.begin(), stack.end(), handler_key) !=
                    stack.end()) {
                    if (debug_venue_filters_enabled()) {
                        std::fprintf(
                            stderr,
                            "[world] venue script recursion skipped: %s\n",
                            handler_key.c_str());
                    }
                    break;
                }
                if (!handler) break;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script call %s\n",
                                 handler_key.c_str());
                }
                stack.push_back(handler_key);
                if (!handler->parameters.empty()) {
                    std::map<std::string, std::vector<std::string>> bindings =
                        variables ? *variables
                                  : std::map<std::string,
                                             std::vector<std::string>>{};
                    for (size_t i = 0; i < handler->parameters.size(); ++i) {
                        bindings[handler->parameters[i]] =
                            i < step.arguments.size()
                                ? resolve_argument(step.arguments[i])
                                : std::vector<std::string>{};
                    }
                    execute_venue_script_steps(handler->steps, stack,
                                               &bindings);
                } else {
                    execute_venue_script_steps(handler->steps, stack,
                                               variables);
                }
                stack.pop_back();
                break;
            }
            case VenueScriptStep::Kind::FireFilter:
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script animate %s\n",
                                 step.name.c_str());
                }
                apply_venue_event(step.name, false);
                break;
            case VenueScriptStep::Kind::AnimateEnv: {
                std::string target = step.name;
                if (step.target_is_property_ref &&
                    !venue_script_context_object_.empty()) {
                    const auto object_it =
                        venue_script_objects_.find(venue_script_context_object_);
                    if (object_it != venue_script_objects_.end()) {
                        const auto prop_it =
                            object_it->second.properties.find(step.name);
                        if (prop_it != object_it->second.properties.end())
                            target = prop_it->second;
                    }
                }
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] venue script animate-env target=%s resolved=%s dest=%.2f period=%.3f object=%s\n",
                        step.name.c_str(), target.c_str(),
                        step.anim_dest_frame, step.anim_period,
                        venue_script_context_object_.c_str());
                }
                VenueScriptStep resolved = step;
                resolved.name = target;
                if (resolved.anim_has_range) {
                    apply_venue_script_animation(resolved);
                } else {
                    resolved.kind = VenueScriptStep::Kind::AnimateTo;
                    apply_venue_script_animate_to(resolved);
                }
                break;
            }
            case VenueScriptStep::Kind::AnimateObject: {
                if (venue_script_context_object_.empty()) break;
                const double period =
                    step.anim_period_random
                        ? venue_script_random_float(step.anim_period,
                                                    step.anim_period_max)
                        : static_cast<double>(step.anim_period);
                const float start =
                    step.anim_has_range ? step.anim_start_frame : 0.0f;
                const float end =
                    step.anim_has_range ? step.anim_end_frame
                                        : step.anim_dest_frame;
                start_venue_proxy_object_animation(
                    venue_script_context_object_, start, end,
                    static_cast<float>(std::max(0.0, period)));
                break;
            }
            case VenueScriptStep::Kind::AnimateTo:
                apply_venue_script_animate_to(step);
                break;
            case VenueScriptStep::Kind::AnimTask:
                apply_venue_script_animation(step);
                break;
            case VenueScriptStep::Kind::SwitchAnim: {
                VenueScriptStep resolved = step;
                if (step.name_is_variable && variables) {
                    const auto it = variables->find(step.name);
                    if (it == variables->end() || it->second.empty()) break;
                    resolved.name = it->second.front();
                    resolved.name_is_variable = false;
                }
                if (step.anim_start_random) {
                    resolved.anim_start_frame = std::floor(
                        venue_script_random_float(
                            step.anim_start_frame,
                            step.anim_start_frame_max + 1.0f));
                    resolved.anim_start_random = false;
                }
                apply_venue_script_animation(resolved);
                break;
            }
            case VenueScriptStep::Kind::SetObjectShowing:
                if (!venue_script_context_object_.empty()) {
                    set_venue_proxy_object_showing(
                        venue_script_context_object_, step.value != 0);
                }
                break;
            case VenueScriptStep::Kind::SetNamedObjectShowing: {
                const bool showing =
                    step.has_expression
                        ? evaluate_venue_script_expression(step.expression) !=
                              "0"
                        : step.value != 0;
                if (!venue_script_namespace_role_.empty()) {
                    set_namespaced_performer_object_showing(
                        venue_script_namespace_role_, step.name, showing);
                } else {
                    set_legacy_venue_object_showing(step.name, showing);
                }
                break;
            }
            case VenueScriptStep::Kind::SetSingerEnvironment:
                legacy_gh1_singer_environment_ = step.name;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] GH1 singer environment: %s source=arena::set_singer_env\n",
                        legacy_gh1_singer_environment_.c_str());
                }
                break;
            case VenueScriptStep::Kind::AddTransformChild: {
                const std::string parent = canonical_milo_ref(step.name);
                const std::string child = canonical_milo_ref(step.target);
                venue_transform_parent_overrides_[child] = parent;
                if (world_) {
                    world_->set_transform_parent_overrides(
                        venue_transform_parent_overrides_);
                }
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] GH1 add_trans parent=%s child=%s source=RndTransformable::add_trans local_preserved=1\n",
                        parent.c_str(), child.c_str());
                }
                break;
            }
            case VenueScriptStep::Kind::SetFlareSteps: {
                std::string target = step.name;
                if (step.name_is_variable && variables) {
                    const auto it = variables->find(step.name);
                    if (it == variables->end() || it->second.empty()) break;
                    target = it->second.front();
                }
                target = canonical_milo_ref(target);
                venue_flare_steps_[target] = step.value;
                if (world_) world_->set_flare_steps(venue_flare_steps_);
                if (lighting_) {
                    lighting_->set_flare_steps(venue_flare_steps_);
                }
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] GH1 Flare::SetSteps target=%s steps=%d source=RndFlare::Handle(set_steps)\n",
                        target.c_str(), step.value);
                }
                break;
            }
            case VenueScriptStep::Kind::UnhookAnimParents: {
                const std::string target = canonical_milo_ref(step.name);
                size_t removed = 0;
                const auto erase_target = [&](auto& groups) {
                    for (auto& [parent, children] : groups) {
                        (void)parent;
                        const size_t before = children.size();
                        children.erase(
                            std::remove_if(
                                children.begin(), children.end(),
                                [&](const std::string& child) {
                                    return canonical_milo_ref(child) == target;
                                }),
                            children.end());
                        removed += before - children.size();
                    }
                };
                erase_target(venue_anim_group_children_);
                erase_target(lighting_anim_group_children_);
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] GH1 unhook_anim_parents target=%s removed=%zu\n",
                        target.c_str(), removed);
                }
                break;
            }
            case VenueScriptStep::Kind::RemoveAnim: {
                const std::string parent = canonical_milo_ref(step.name);
                const std::string target = canonical_milo_ref(step.target);
                size_t removed = 0;
                const auto remove_from_parent = [&](auto& groups) {
                    const auto it = groups.find(parent);
                    if (it == groups.end()) return;
                    const size_t before = it->second.size();
                    it->second.erase(
                        std::remove_if(
                            it->second.begin(), it->second.end(),
                            [&](const std::string& child) {
                                return canonical_milo_ref(child) == target;
                            }),
                        it->second.end());
                    removed += before - it->second.size();
                };
                remove_from_parent(venue_anim_group_children_);
                remove_from_parent(lighting_anim_group_children_);
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] GH1 remove_anim parent=%s target=%s removed=%zu\n",
                        parent.c_str(), target.c_str(), removed);
                }
                break;
            }
            case VenueScriptStep::Kind::StopObjectAnimation:
                if (!venue_script_context_object_.empty())
                    stop_venue_proxy_object_animation(
                        venue_script_context_object_);
                break;
            case VenueScriptStep::Kind::IfAllStates: {
                bool enabled = true;
                for (const auto& state : step.state_names) {
                    const auto state_key =
                        venue_script_context_state_key(state);
                    const auto state_it = venue_script_state_.find(state_key);
                    if (state_it == venue_script_state_.end() ||
                        state_it->second == 0) {
                        enabled = false;
                        break;
                    }
                }
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script if-all states=%zu result=%d\n",
                                 step.state_names.size(), enabled ? 1 : 0);
                }
                if (enabled)
                    execute_venue_script_steps(step.children, stack,
                                               variables);
                break;
            }
            case VenueScriptStep::Kind::IfObjectExists: {
                bool enabled =
                    venue_script_objects_.find(step.name) !=
                    venue_script_objects_.end();
                if (!enabled) {
                    enabled = std::any_of(
                        performers_.begin(), performers_.end(),
                        [&](const Performer& performer) {
                            return performer.role == step.name;
                        });
                }
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script if-object-exists %s result=%d\n",
                                 step.name.c_str(), enabled ? 1 : 0);
                }
                if (enabled)
                    execute_venue_script_steps(step.children, stack,
                                               variables);
                break;
            }
            case VenueScriptStep::Kind::IfElse: {
                const bool enabled =
                    evaluate_venue_script_expression(step.expression) != "0";
                execute_venue_script_steps(
                    enabled ? step.children : step.else_children, stack,
                    variables);
                break;
            }
            case VenueScriptStep::Kind::WithNamespace: {
                const std::string previous = venue_script_namespace_role_;
                venue_script_namespace_role_ = step.name;
                execute_venue_script_steps(step.children, stack, variables);
                venue_script_namespace_role_ = previous;
                break;
            }
            case VenueScriptStep::Kind::IfStateEquals: {
                const auto state_key =
                    venue_script_context_state_key(step.name);
                const auto state_it = venue_script_state_.find(state_key);
                const int actual =
                    state_it == venue_script_state_.end() ? 0
                                                         : state_it->second;
                const bool enabled = actual == step.value;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] venue script if-state %s actual=%d expected=%d result=%d\n",
                        step.name.c_str(), actual, step.value,
                        enabled ? 1 : 0);
                }
                if (enabled)
                    execute_venue_script_steps(step.children, stack,
                                               variables);
                break;
            }
            case VenueScriptStep::Kind::IfExcitementGreater: {
                const uint32_t excitement =
                    venue_excitement_level(active_venue_event_);
                const bool enabled =
                    excitement > static_cast<uint32_t>(std::max(0, step.value));
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] venue script if excitement=%u > %d result=%d\n",
                        excitement, step.value, enabled ? 1 : 0);
                }
                if (enabled)
                    execute_venue_script_steps(step.children, stack,
                                               variables);
                break;
            }
            case VenueScriptStep::Kind::ScheduleTask: {
                schedule_venue_script_task(step);
                break;
            }
            case VenueScriptStep::Kind::CancelTask: {
                if (step.target_is_state_ref)
                    cancel_venue_script_task_state_ref(step.name);
                else
                    cancel_venue_script_task_by_name(step.name);
                break;
            }
            case VenueScriptStep::Kind::TaskSetName:
                if (running_venue_script_task_) {
                    running_venue_script_task_->name = step.name;
                    if (debug_venue_filters_enabled()) {
                        std::fprintf(stderr,
                                     "[world] venue script task %u set_name '%s'\n",
                                     running_venue_script_task_->id,
                                     step.name.c_str());
                    }
                }
                break;
            case VenueScriptStep::Kind::TaskSleep:
            case VenueScriptStep::Kind::TaskLoop:
                break;
            case VenueScriptStep::Kind::ForEach: {
                if (step.arguments.empty()) break;
                const auto values = resolve_argument(step.arguments.front());
                for (const auto& value : values) {
                    std::map<std::string, std::vector<std::string>> bindings =
                        variables ? *variables
                                  : std::map<std::string,
                                             std::vector<std::string>>{};
                    bindings[step.name] = {value};
                    execute_venue_script_steps(step.children, stack,
                                               &bindings);
                }
                break;
            }
            case VenueScriptStep::Kind::Switch: {
                try {
                    std::string selected;
                    if (step.has_expression) {
                        selected =
                            evaluate_venue_script_expression(step.expression);
                    } else if (variables) {
                        const auto selector = variables->find(step.name);
                        if (selector == variables->end() ||
                            selector->second.empty()) {
                            break;
                        }
                        selected = selector->second.front();
                    } else {
                        break;
                    }
                    const int key = std::stoi(selected);
                    const auto branch = step.switch_branches.find(key);
                    if (branch != step.switch_branches.end())
                        execute_venue_script_steps(branch->second, stack,
                                                   variables);
                } catch (const std::exception&) {
                }
                break;
            }
            case VenueScriptStep::Kind::Unsupported:
                if (debug_venue_filters_enabled()) {
                    std::fprintf(
                        stderr,
                        "[world] unsupported GH1 venue script operation: %s\n",
                        (step.target.empty()
                             ? step.name
                             : step.name + "::" + step.target)
                            .c_str());
                }
                break;
        }
    }
}

void Gameplay::execute_venue_script_event(
    const std::string& event_name,
    const std::map<std::string, std::vector<std::string>>* variables) {
    if (executing_venue_script_) return;
    const auto handler_it = venue_script_handlers_.find(event_name);
    if (handler_it == venue_script_handlers_.end()) return;
    executing_venue_script_ = true;
    const std::string prev_object = venue_script_context_object_;
    const std::string prev_type = venue_script_context_type_;
    venue_script_context_object_.clear();
    venue_script_context_type_.clear();
    std::vector<std::string> stack;
    stack.push_back(event_name);
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr, "[world] venue script event %s\n",
                     event_name.c_str());
    }
    execute_venue_script_steps(handler_it->second.steps, stack, variables);
    venue_script_context_object_ = prev_object;
    venue_script_context_type_ = prev_type;
    executing_venue_script_ = false;
}

double Gameplay::venue_script_random_float(double min_value, double max_value) {
    if (max_value < min_value) std::swap(min_value, max_value);
    venue_script_rng_state_ =
        venue_script_rng_state_ * 1664525u + 1013904223u;
    const double unit =
        static_cast<double>((venue_script_rng_state_ >> 8) & 0x00ffffffu) /
        static_cast<double>(0x01000000u);
    return min_value + (max_value - min_value) * unit;
}

double Gameplay::venue_script_delay_seconds(double amount,
                                            bool beat_units) const {
    amount = std::max(0.0, amount);
    if (!beat_units || chart_.ticks_per_beat == 0) return amount;
    const uint32_t now_tick = chart_.sec_to_tick(song_time_);
    const uint32_t delta_ticks =
        static_cast<uint32_t>(std::round(
            amount * static_cast<double>(chart_.ticks_per_beat)));
    const double target_time = chart_.tick_to_sec(now_tick + delta_ticks);
    return std::max(0.0, target_time - song_time_);
}

double Gameplay::venue_script_delay_seconds(const VenueScriptStep& step,
                                            bool inherited_beat_units) {
    const double amount =
        step.delay_random
            ? venue_script_random_float(step.delay, step.delay_max)
            : step.delay;
    const bool beat_units = step.task_beat_units || inherited_beat_units;
    return venue_script_delay_seconds(amount, beat_units);
}

void Gameplay::clear_venue_script_task_refs(uint32_t id) {
    for (auto it = venue_script_object_state_.begin();
         it != venue_script_object_state_.end();) {
        if (it->second == id)
            it = venue_script_object_state_.erase(it);
        else
            ++it;
    }
}

uint32_t Gameplay::schedule_venue_script_task(const VenueScriptStep& step) {
    ActiveVenueScriptTask task;
    task.id = next_venue_script_task_id_++;
    task.name = step.name;
    task.object_name = venue_script_context_object_;
    task.object_type = venue_script_context_type_;
    task.state_slot = step.assign_state.empty()
                          ? std::string()
                          : venue_script_context_state_key(step.assign_state);
    task.steps = step.children;
    task.thread = step.task_thread;
    task.beat_units = step.task_beat_units;
    task.cursor = 0;
    task.due_time = song_time_ + venue_script_delay_seconds(step, false);
    venue_script_tasks_.push_back(std::move(task));
    ActiveVenueScriptTask& stored = venue_script_tasks_.back();
    if (!stored.state_slot.empty()) {
        venue_script_object_state_[stored.state_slot] = stored.id;
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(
            stderr,
            "[world] venue script schedule %s id=%u name='%s' object='%s' state='%s' delay=%.3f due=%.3f steps=%zu units=%s\n",
            stored.thread ? "thread_task" : "script_task", stored.id,
            stored.name.c_str(), stored.object_name.c_str(),
            stored.state_slot.c_str(),
            stored.due_time - song_time_, stored.due_time, stored.steps.size(),
            stored.beat_units ? "beats" : "seconds");
    }
    return stored.id;
}

void Gameplay::cancel_venue_script_task_by_id(uint32_t id) {
    if (id == 0) return;
    bool canceled = false;
    for (auto& task : venue_script_tasks_) {
        if (task.id == id) {
            task.canceled = true;
            canceled = true;
        }
    }
    if (running_venue_script_task_ && running_venue_script_task_->id == id) {
        running_venue_script_task_->canceled = true;
        canceled = true;
    }
    clear_venue_script_task_refs(id);
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr,
                     "[world] venue script cancel id=%u canceled=%d\n", id,
                     canceled ? 1 : 0);
    }
}

void Gameplay::cancel_venue_script_task_by_name(const std::string& name) {
    if (name.empty()) return;
    bool canceled = false;
    for (auto& task : venue_script_tasks_) {
        if (task.name == name &&
            task.object_name == venue_script_context_object_) {
            task.canceled = true;
            clear_venue_script_task_refs(task.id);
            canceled = true;
        }
    }
    if (running_venue_script_task_ &&
        running_venue_script_task_->name == name &&
        running_venue_script_task_->object_name ==
            venue_script_context_object_) {
        running_venue_script_task_->canceled = true;
        clear_venue_script_task_refs(running_venue_script_task_->id);
        canceled = true;
    }
    if (debug_venue_filters_enabled()) {
        std::fprintf(stderr,
                     "[world] venue script cancel name='%s' object='%s' canceled=%d\n",
                     name.c_str(), venue_script_context_object_.c_str(),
                     canceled ? 1 : 0);
    }
}

void Gameplay::cancel_venue_script_task_state_ref(
    const std::string& state_name) {
    const std::string state_key = venue_script_context_state_key(state_name);
    const auto it = venue_script_object_state_.find(state_key);
    if (it == venue_script_object_state_.end()) {
        if (debug_venue_filters_enabled()) {
            std::fprintf(stderr,
                         "[world] venue script cancel state='%s' missing\n",
                         state_key.c_str());
        }
        return;
    }
    const uint32_t id = it->second;
    venue_script_object_state_.erase(it);
    cancel_venue_script_task_by_id(id);
}

bool Gameplay::venue_script_task_exists(const std::string& name) const {
    if (name.empty()) return false;
    if (running_venue_script_task_ && !running_venue_script_task_->canceled &&
        running_venue_script_task_->name == name &&
        running_venue_script_task_->object_name ==
            venue_script_context_object_) {
        return true;
    }
    for (const auto& task : venue_script_tasks_) {
        if (!task.canceled && task.name == name &&
            task.object_name == venue_script_context_object_) {
            return true;
        }
    }
    return false;
}

void Gameplay::update_venue_script_tasks() {
    const size_t tasks_to_scan = venue_script_tasks_.size();
    size_t scanned = 0;
    for (size_t i = 0; i < venue_script_tasks_.size() &&
                       scanned < tasks_to_scan;) {
        ++scanned;
        if (venue_script_tasks_[i].canceled) {
            clear_venue_script_task_refs(venue_script_tasks_[i].id);
            venue_script_tasks_.erase(venue_script_tasks_.begin() + i);
            continue;
        }
        if (venue_script_tasks_[i].due_time > song_time_ + 0.0001) {
            ++i;
            continue;
        }

        ActiveVenueScriptTask task = std::move(venue_script_tasks_[i]);
        venue_script_tasks_.erase(venue_script_tasks_.begin() + i);
        if (debug_venue_filters_enabled()) {
            std::fprintf(stderr,
                         "[world] venue script task run id=%u name='%s' cursor=%zu steps=%zu t=%.3f\n",
                         task.id, task.name.c_str(), task.cursor,
                         task.steps.size(), song_time_);
        }

        bool paused = false;
        bool looped = false;
        const std::string prev_object = venue_script_context_object_;
        const std::string prev_type = venue_script_context_type_;
        venue_script_context_object_ = task.object_name;
        venue_script_context_type_ = task.object_type;
        running_venue_script_task_ = &task;
        std::vector<std::string> stack;
        while (!task.canceled && task.cursor < task.steps.size()) {
            const VenueScriptStep& step = task.steps[task.cursor];
            if (step.kind == VenueScriptStep::Kind::TaskSleep) {
                const double delay =
                    venue_script_delay_seconds(step, task.beat_units);
                ++task.cursor;
                task.due_time = song_time_ + delay;
                paused = true;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script task sleep id=%u delay=%.3f due=%.3f cursor=%zu\n",
                                 task.id, delay, task.due_time, task.cursor);
                }
                break;
            }
            if (step.kind == VenueScriptStep::Kind::TaskLoop) {
                task.cursor = 0;
                task.due_time = song_time_;
                paused = true;
                looped = true;
                if (debug_venue_filters_enabled()) {
                    std::fprintf(stderr,
                                 "[world] venue script task loop id=%u\n",
                                 task.id);
                }
                break;
            }
            std::vector<VenueScriptStep> single;
            single.push_back(step);
            execute_venue_script_steps(single, stack);
            ++task.cursor;
        }
        running_venue_script_task_ = nullptr;
        venue_script_context_object_ = prev_object;
        venue_script_context_type_ = prev_type;

        if (task.canceled || (!paused && task.cursor >= task.steps.size())) {
            clear_venue_script_task_refs(task.id);
            if (debug_venue_filters_enabled()) {
                std::fprintf(stderr,
                             "[world] venue script task done id=%u canceled=%d\n",
                             task.id, task.canceled ? 1 : 0);
            }
            continue;
        }
        if (looped && task.steps.empty()) {
            clear_venue_script_task_refs(task.id);
            continue;
        }
        venue_script_tasks_.push_back(std::move(task));
    }
}

void Gameplay::apply_venue_event(const std::string& event_name,
                                 bool persistent,
                                 bool force_persistent,
                                 int next_link_depth) {
    if (event_name.empty()) return;
    const bool debug_venue = debug_venue_filters_enabled();
    if (persistent && !world_) {
        active_venue_event_ = event_name;
        if (debug_venue) {
            std::fprintf(stderr,
                         "[world] venue event %s: latched until venue load\n",
                         event_name.c_str());
        }
        return;
    }
    if (!persistent && !world_) {
        push_unique_ref(pending_transient_venue_events_, event_name);
        if (debug_venue) {
            std::fprintf(stderr,
                         "[world] venue event %s: queued until venue load\n",
                         event_name.c_str());
        }
        return;
    }
    // Persistent venue state is edge-triggered. The gameplay presentation
    // asks for the current excitement state every frame, but retail Arena
    // handlers and their switch_anim tasks run only when that state changes.
    // Deduplicate before script dispatch so a stable state cannot restart
    // authored loops at frame zero on every poll.
    if (persistent && active_venue_event_ == event_name && world_ &&
        !force_persistent) {
        return;
    }
    bool peak_transition = false;
    std::string peak_transition_event;
    bool persistent_had_environment_color = false;
    bool persistent_had_environment_fog = false;
    bool persistent_had_light_color = false;
    bool persistent_had_light_state = false;
    if (persistent) {
        const bool was_peak = is_peak_excitement_event(active_venue_event_);
        const bool is_peak = is_peak_excitement_event(event_name);
        peak_transition = was_peak != is_peak;
        peak_transition_event = is_peak ? "peak_on" : "peak_off";
        active_venue_event_ = event_name;
        if (world_) {
            // GH1 Arena::Crowd::update_crowd supplies the same 10/25/50/100%
            // boot/bad/okay/great progression to both SetSizes arguments.
            // Unlike GH2 WorldCrowd, GH1 has no widescreen 70% cap.
            const float gh1_crowd_size =
                worldcrowd_fullness_for_event(active_venue_event_, false);
            if (env_value("GHOGX_DIAGNOSTIC_GH1_CROWD_3D_ONLY")) {
                // Venue-preview proof mode: fill the camera-selected source
                // region with promoted 3-D actors and suppress every flat
                // card outside it. This is diagnostic-only; normal gameplay
                // retains Arena::Crowd's authored promoted/flat fractions.
                world_->set_gh1_crowd_sizes(1.0f, 0.0f);
            } else {
                world_->set_gh1_crowd_sizes(gh1_crowd_size,
                                            gh1_crowd_size);
            }
        }
        // Excitement is a source event, not an instruction to delete every
        // AnimTask. Incoming tasks adopt the previous task for their actual
        // AnimTarget below; unrelated authored tasks keep running.
        active_venue_material_anims_.erase(
            std::remove_if(active_venue_material_anims_.begin(),
                           active_venue_material_anims_.end(),
                           [](const ActiveVenueMaterialAnim& active) {
                               return active.persistent;
                           }),
            active_venue_material_anims_.end());
        active_venue_environment_anims_.erase(
            std::remove_if(active_venue_environment_anims_.begin(),
                           active_venue_environment_anims_.end(),
                           [](const ActiveVenueEnvironmentAnim& active) {
                               return active.persistent;
                           }),
            active_venue_environment_anims_.end());
        active_venue_light_anims_.erase(
            std::remove_if(active_venue_light_anims_.begin(),
                           active_venue_light_anims_.end(),
                           [](const ActiveVenueLightAnim& active) {
                               return active.persistent;
                           }),
            active_venue_light_anims_.end());
        active_venue_particles_.erase(
            std::remove_if(active_venue_particles_.begin(),
                           active_venue_particles_.end(),
                           [](const ActiveVenueParticleSystem& active) {
                               return active.persistent;
                           }),
            active_venue_particles_.end());
        venue_mesh_translation_offsets_.clear();
        persistent_had_environment_color =
            !venue_environment_colors_.empty();
        persistent_had_environment_fog =
            !venue_environment_fog_colors_.empty() ||
            !venue_environment_fog_ranges_.empty() ||
            !venue_environment_fog_enabled_.empty();
        persistent_had_light_color = !venue_light_colors_.empty();
        persistent_had_light_state = !venue_light_state_overrides_.empty();
        venue_environment_colors_.clear();
        venue_environment_fog_colors_.clear();
        venue_environment_fog_ranges_.clear();
        venue_environment_fog_enabled_.clear();
        venue_light_colors_.clear();
        venue_light_state_overrides_.clear();
    }
    update_venue_event_trigger_gates(event_name);
    const bool venue_event_trigger_routes_enabled =
        venue_event_route_enabled_by_triggers(event_name);
    if (venue_script_sections_ready_)
        execute_venue_script_event(event_name);
    constexpr std::string_view player_fret_prefix = "hit_p0_fret";
    if (venue_script_sections_ready_ &&
        venue_script_handlers_.find("hit_gem") !=
            venue_script_handlers_.end() &&
        event_name.rfind(player_fret_prefix, 0) == 0) {
        try {
            const int fret =
                std::stoi(event_name.substr(player_fret_prefix.size()));
            if (fret >= 1 && fret <= 5) {
                const std::map<std::string, std::vector<std::string>>
                    gh1_message_arguments = {
                        {"slot", {std::to_string(fret - 1)}}};
                execute_venue_script_event("hit_gem",
                                           &gh1_message_arguments);
            }
        } catch (const std::exception&) {
        }
    }
    if (!venue_event_trigger_routes_enabled) {
        if (debug_venue) {
            std::fprintf(
                stderr,
                "[world] venue event %s: skipped by disabled EventTrigger gate\n",
                event_name.c_str());
        }
        return;
    }
    const bool venue_script_object_applied =
        execute_venue_script_object_messages(venue_event_script_messages_,
                                             event_name);
    std::vector<std::pair<std::string, float>> material_changes;
    bool material_color_changed = false;
    bool material_texture_changed = false;
    bool material_tex_changed = false;
    bool environment_color_changed = false;
    bool environment_fog_changed = false;
    bool light_color_changed = false;
    bool light_state_changed = false;
    bool venue_route_applied = false;
    if (persistent) {
        environment_color_changed = persistent_had_environment_color;
        environment_fog_changed = persistent_had_environment_fog;
        light_color_changed = persistent_had_light_color;
        light_state_changed = persistent_had_light_state;
    }
    if (peak_transition) {
        if (debug_venue) {
            std::fprintf(stderr,
                         "[world] venue peak bridge %s -> %s\n",
                         event_name.c_str(),
                         peak_transition_event.c_str());
        }
        apply_venue_event(peak_transition_event, false);
        venue_route_applied = true;
    } else if (persistent && force_persistent &&
               is_peak_excitement_event(event_name)) {
        venue_route_applied = true;
    }
    auto event_it = venue_event_mat_anims_.find(event_name);
    const bool has_decoded_route_entry =
        event_it != venue_event_mat_anims_.end() ||
        venue_event_env_anims_.find(event_name) != venue_event_env_anims_.end() ||
        venue_event_light_anims_.find(event_name) !=
            venue_event_light_anims_.end() ||
        venue_event_particle_systems_.find(event_name) !=
            venue_event_particle_systems_.end() ||
        venue_event_anim_filters_.find(event_name) !=
            venue_event_anim_filters_.end() ||
        venue_event_group_visibility_.find(event_name) !=
            venue_event_group_visibility_.end() ||
        venue_event_script_messages_.find(event_name) !=
            venue_event_script_messages_.end() ||
        lighting_event_mat_anims_.find(event_name) !=
            lighting_event_mat_anims_.end() ||
        lighting_event_env_anims_.find(event_name) !=
            lighting_event_env_anims_.end() ||
        lighting_event_light_anims_.find(event_name) !=
            lighting_event_light_anims_.end() ||
        lighting_event_particle_systems_.find(event_name) !=
            lighting_event_particle_systems_.end() ||
        lighting_event_anim_filters_.find(event_name) !=
            lighting_event_anim_filters_.end() ||
        lighting_event_group_visibility_.find(event_name) !=
            lighting_event_group_visibility_.end() ||
        lighting_event_script_messages_.find(event_name) !=
            lighting_event_script_messages_.end() ||
        (!diagnostic_venue_event_.empty() &&
         diagnostic_venue_event_ == event_name);
    if (event_it != venue_event_mat_anims_.end()) {
        for (const auto& route : event_it->second) {
            auto anim_it = venue_mat_anims_.find(route.anim);
            if (anim_it == venue_mat_anims_.end()) continue;
            const auto& anim = anim_it->second;
            const bool has_tex_transform =
                !anim.tex_translation_keys.empty() ||
                !anim.tex_scale_keys.empty() ||
                !anim.tex_rotation_keys.empty();
            const bool has_color = !anim.color_keys.empty();
            const bool has_texture = !anim.texture_keys.empty();
            if (!has_color && !has_texture && !anim.has_alpha &&
                !has_tex_transform) {
                continue;
            }
            const float route_delay =
                source_anim_delay_seconds(route.source_delay_seconds);
            const double wait_seconds =
                route.source_wait
                    ? venue_material_anim_wait_seconds(
                          active_venue_material_anims_, anim.material,
                          song_time_)
                    : 0.0;
            const double start_delay =
                static_cast<double>(route_delay) + wait_seconds;
            const bool delayed_start = start_delay > 0.001;
            active_venue_material_anims_.erase(
                std::remove_if(active_venue_material_anims_.begin(),
                               active_venue_material_anims_.end(),
                               [&](const ActiveVenueMaterialAnim& active) {
                                   return active.material == anim.material;
                               }),
                active_venue_material_anims_.end());
            ActiveVenueMaterialAnim active_anim;
            active_anim.name = anim.name;
            active_anim.material = anim.material;
            active_anim.has_alpha = anim.has_alpha;
            active_anim.start_alpha =
                anim.has_alpha
                    ? current_material_alpha(anim.material,
                                             venue_material_alpha_,
                                             venue_material_defaults_,
                                             anim.start_alpha)
                    : 1.0f;
            active_anim.end_alpha = anim.end_alpha;
            active_anim.start_time = song_time_ + start_delay;
            active_anim.duration_frames = anim.duration_frames;
            active_anim.color_keys = anim.color_keys;
            active_anim.alpha_keys = anim.alpha_keys;
            active_anim.texture_keys = anim.texture_keys;
            active_anim.tex_translation_keys = anim.tex_translation_keys;
            active_anim.tex_scale_keys = anim.tex_scale_keys;
            active_anim.tex_rotation_keys = anim.tex_rotation_keys;
            active_anim.persistent = persistent;
            active_anim.source_blend_period_seconds =
                route.source_blend_period_seconds;
            active_anim.source_start_delay_seconds =
                static_cast<float>(start_delay);
            active_anim.has_source_filter = route.has_source_filter;
            if (route.has_source_filter) {
                active_anim.source_filter = route.source_filter;
            }
            active_anim.duration_seconds = material_anim_route_duration_seconds(
                route, anim.duration_frames, &chart_, active_anim.start_time);
            if (has_color) {
                active_anim.has_start_color = true;
                active_anim.start_color =
                    current_material_color(anim.material,
                                           venue_material_colors_,
                                           venue_material_defaults_);
            }
            if (has_tex_transform) {
                active_anim.has_start_tex_transform = true;
                active_anim.start_tex_transform =
                    current_material_tex_transform(anim.material,
                                                   venue_material_tex_transforms_,
                                                   venue_material_defaults_);
            }
            const float initial_blend = source_anim_blend_at(
                active_anim.source_blend_period_seconds, 0.0);
            const float initial_frame =
                active_material_anim_initial_frame(active_anim, &chart_);
            if (!delayed_start && anim.has_alpha) {
                const float sampled_alpha =
                    active_anim.alpha_keys.empty()
                        ? active_anim.start_alpha
                        : clamp_material_alpha(sample_material_float_key(
                              active_anim.alpha_keys, initial_frame));
                venue_material_alpha_[anim.material] =
                    blend_material_alpha(active_anim.start_alpha,
                                         sampled_alpha, initial_blend);
                material_changes.push_back({anim.material, anim.end_alpha});
            }
            if (!delayed_start && has_color) {
                venue_material_colors_[anim.material] = blend_material_color(
                    active_anim.start_color,
                    sample_material_color_key(anim.color_keys, initial_frame),
                    initial_blend);
                material_color_changed = true;
            }
            if (!delayed_start && has_texture) {
                venue_material_textures_[anim.material] =
                    sample_material_texture_key(anim.texture_keys,
                                                initial_frame);
                material_texture_changed = true;
            }
            if (!delayed_start && has_tex_transform) {
                venue_material_tex_transforms_[anim.material] =
                    blend_material_tex_transform(
                        active_anim.start_tex_transform,
                        sample_material_tex_transform(anim, initial_frame),
                        initial_blend);
                material_tex_changed = true;
            }
            venue_route_applied = true;
            if (debug_venue) {
                std::fprintf(stderr,
                             "[world] venue event %s: MatAnim %s -> %s alpha %.3f -> %.3f color_keys=%zu alpha_keys=%zu texture_keys=%zu tex_trans_keys=%zu tex_scale_keys=%zu tex_rot_keys=%zu seconds=%.3f blend_period=%.3f wait=%d delay=%.3f inherited_wait=%.3f filter=%s %s\n",
                             event_name.c_str(), route.anim.c_str(),
                             anim.material.c_str(), active_anim.start_alpha,
                             active_anim.end_alpha,
                             active_anim.color_keys.size(),
                             active_anim.alpha_keys.size(),
                             active_anim.texture_keys.size(),
                             active_anim.tex_translation_keys.size(),
                             active_anim.tex_scale_keys.size(),
                             active_anim.tex_rotation_keys.size(),
                             active_anim.duration_seconds,
                             active_anim.source_blend_period_seconds,
                             route.source_wait ? 1 : 0, route_delay,
                             wait_seconds,
                             active_anim.has_source_filter
                                 ? active_anim.source_filter.name.c_str()
                                 : "none",
                             persistent ? "persistent" : "transient");
            }
            if (active_anim.duration_seconds <= 0.0001 && !delayed_start) {
                const float terminal_frame =
                    active_material_anim_terminal_frame(active_anim, &chart_);
                if (anim.has_alpha)
                    venue_material_alpha_[anim.material] = blend_material_alpha(
                        active_anim.start_alpha,
                        anim.alpha_keys.empty()
                            ? anim.end_alpha
                            : clamp_material_alpha(sample_material_float_key(
                                  anim.alpha_keys, terminal_frame)),
                        source_anim_blend_at(
                            active_anim.source_blend_period_seconds,
                            active_anim.duration_seconds));
                if (has_color) {
                    venue_material_colors_[anim.material] =
                        blend_material_color(
                            active_anim.start_color,
                            sample_material_color_key(
                                anim.color_keys, terminal_frame),
                            source_anim_blend_at(
                                active_anim.source_blend_period_seconds,
                                active_anim.duration_seconds));
                }
                if (has_texture) {
                    venue_material_textures_[anim.material] =
                        sample_material_texture_key(
                            anim.texture_keys, terminal_frame);
                }
                if (has_tex_transform) {
                    venue_material_tex_transforms_[anim.material] =
                        blend_material_tex_transform(
                            active_anim.start_tex_transform,
                            sample_material_tex_transform(
                                anim, terminal_frame),
                            source_anim_blend_at(
                                active_anim.source_blend_period_seconds,
                                active_anim.duration_seconds));
                }
            } else {
                active_venue_material_anims_.push_back(std::move(active_anim));
            }
        }
    }
    if (const auto env_event_it = venue_event_env_anims_.find(event_name);
        env_event_it != venue_event_env_anims_.end()) {
        for (const auto& route : env_event_it->second) {
            const auto anim_it = venue_env_anims_.find(route.anim);
            if (anim_it == venue_env_anims_.end()) continue;
            const auto& anim = anim_it->second;
            if (!venue_environment_anim_has_keys(anim)) continue;
            const float route_delay =
                source_anim_delay_seconds(route.source_delay_seconds);
            const double wait_seconds =
                route.source_wait
                    ? venue_environment_anim_wait_seconds(
                          active_venue_environment_anims_, anim.environment,
                          song_time_)
                    : 0.0;
            const double start_delay =
                static_cast<double>(route_delay) + wait_seconds;
            const bool delayed_start = start_delay > 0.001;
            active_venue_environment_anims_.erase(
                std::remove_if(active_venue_environment_anims_.begin(),
                               active_venue_environment_anims_.end(),
                               [&](const ActiveVenueEnvironmentAnim& active) {
                                   return active.environment == anim.environment;
                               }),
                active_venue_environment_anims_.end());
            ActiveVenueEnvironmentAnim active_anim;
            active_anim.name = anim.name;
            active_anim.environment = anim.environment;
            active_anim.start_time = song_time_ + start_delay;
            active_anim.duration_frames = anim.duration_frames;
            active_anim.duration_seconds = event_anim_route_duration_seconds(
                route, anim.duration_frames, &chart_, active_anim.start_time);
            active_anim.color_keys = anim.color_keys;
            active_anim.fog_color_keys = anim.fog_color_keys;
            active_anim.fog_range_keys = anim.fog_range_keys;
            active_anim.persistent = persistent;
            active_anim.source_blend_period_seconds =
                route.source_blend_period_seconds;
            active_anim.source_start_delay_seconds =
                static_cast<float>(start_delay);
            active_anim.has_source_filter = route.has_source_filter;
            if (route.has_source_filter) {
                active_anim.source_filter = route.source_filter;
            }
            const float initial_frame =
                active_environment_anim_initial_frame(active_anim, &chart_);
            if (!delayed_start) {
                venue_environment_frames_[anim.environment] = initial_frame;
                sample_environment_anim_tracks_blended(
                    anim.environment, active_anim.color_keys,
                    active_anim.fog_color_keys, active_anim.fog_range_keys,
                    initial_frame,
                    source_anim_blend_at(
                        active_anim.source_blend_period_seconds, 0.0),
                    venue_environs_,
                    venue_environment_colors_, venue_environment_fog_colors_,
                    venue_environment_fog_ranges_, environment_color_changed,
                    environment_fog_changed);
            }
            venue_route_applied = true;
            if (debug_venue) {
                std::fprintf(
                    stderr,
                    "[world] venue event %s: EnvAnim %s -> %s color_keys=%zu fog_color_keys=%zu fog_range_keys=%zu frames=%.1f seconds=%.3f blend_period=%.3f wait=%d delay=%.3f inherited_wait=%.3f filter=%s %s\n",
                    event_name.c_str(), anim.name.c_str(),
                    anim.environment.c_str(), anim.color_keys.size(),
                    anim.fog_color_keys.size(), anim.fog_range_keys.size(),
                    anim.duration_frames,
                    active_anim.duration_seconds,
                    active_anim.source_blend_period_seconds,
                    route.source_wait ? 1 : 0, route_delay, wait_seconds,
                    route.has_source_filter ? route.source_filter.name.c_str()
                                            : "none",
                    persistent ? "persistent" : "transient");
            }
            if (active_anim.duration_seconds > 0.001 ||
                anim.duration_frames > 0.001f || delayed_start) {
                active_venue_environment_anims_.push_back(std::move(active_anim));
            }
        }
    }
    if (const auto light_event_it =
            venue_event_light_anims_.find(event_name);
        light_event_it != venue_event_light_anims_.end()) {
        for (const auto& route : light_event_it->second) {
            const auto anim_it = venue_light_anims_.find(route.anim);
            if (anim_it == venue_light_anims_.end()) continue;
            const auto& anim = anim_it->second;
            if (anim.color_keys.empty()) continue;
            const float route_delay =
                source_anim_delay_seconds(route.source_delay_seconds);
            const double wait_seconds =
                route.source_wait
                    ? venue_light_anim_wait_seconds(
                          active_venue_light_anims_, anim.light, song_time_)
                    : 0.0;
            const double start_delay =
                static_cast<double>(route_delay) + wait_seconds;
            const bool delayed_start = start_delay > 0.001;
            active_venue_light_anims_.erase(
                std::remove_if(active_venue_light_anims_.begin(),
                               active_venue_light_anims_.end(),
                               [&](const ActiveVenueLightAnim& active) {
                                   return active.light == anim.light;
                               }),
                active_venue_light_anims_.end());
            ActiveVenueLightAnim active_anim;
            active_anim.name = anim.name;
            active_anim.light = anim.light;
            active_anim.start_time = song_time_ + start_delay;
            active_anim.duration_seconds = event_anim_route_duration_seconds(
                route, anim.duration_frames, &chart_, active_anim.start_time);
            active_anim.duration_frames = anim.duration_frames;
            active_anim.color_keys = anim.color_keys;
            active_anim.persistent = persistent;
            active_anim.source_blend_period_seconds =
                route.source_blend_period_seconds;
            active_anim.source_start_delay_seconds =
                static_cast<float>(start_delay);
            active_anim.has_source_filter = route.has_source_filter;
            if (route.has_source_filter) {
                active_anim.source_filter = route.source_filter;
            }
            const float initial_frame =
                active_light_anim_initial_frame(active_anim, &chart_);
            if (!delayed_start) {
                venue_light_colors_[anim.light] = blend_light_color(
                    current_light_color(anim.light, venue_light_colors_,
                                        venue_lights_),
                    sample_light_color_key(active_anim.color_keys,
                                           initial_frame),
                    source_anim_blend_at(
                        active_anim.source_blend_period_seconds, 0.0));
                light_color_changed = true;
            }
            venue_route_applied = true;
            if (debug_venue) {
                std::fprintf(
                    stderr,
                    "[world] venue event %s: LightAnim %s -> %s color_keys=%zu frames=%.1f seconds=%.3f blend_period=%.3f wait=%d delay=%.3f inherited_wait=%.3f filter=%s %s\n",
                    event_name.c_str(), anim.name.c_str(), anim.light.c_str(),
                    anim.color_keys.size(), anim.duration_frames,
                    active_anim.duration_seconds,
                    active_anim.source_blend_period_seconds,
                    route.source_wait ? 1 : 0, route_delay, wait_seconds,
                    route.has_source_filter ? route.source_filter.name.c_str()
                                            : "none",
                    persistent ? "persistent" : "transient");
            }
            if (active_anim.duration_seconds > 0.001 ||
                anim.duration_frames > 0.001f || delayed_start) {
                active_venue_light_anims_.push_back(std::move(active_anim));
            }
        }
    }
    if (const auto particle_it =
            venue_event_particle_systems_.find(event_name);
        particle_it != venue_event_particle_systems_.end()) {
        for (const auto& route : particle_it->second) {
            const float route_delay =
                source_anim_delay_seconds(route.source_delay_seconds);
            const double wait_seconds =
                route.source_wait
                    ? venue_particle_wait_seconds(active_venue_particles_,
                                                  route.particle, song_time_)
                    : 0.0;
            const double start_delay =
                static_cast<double>(route_delay) + wait_seconds;
            active_venue_particles_.erase(
                std::remove_if(active_venue_particles_.begin(),
                               active_venue_particles_.end(),
                               [&](const ActiveVenueParticleSystem& active) {
                                   return active.particle == route.particle &&
                                          active.persistent == persistent;
                               }),
                active_venue_particles_.end());
            ActiveVenueParticleSystem active;
            active.particle = route.particle;
            active.start_time = song_time_ + start_delay;
            active.duration_seconds = particle_route_duration_seconds(
                route, &chart_, active.start_time);
            active.duration_frames = route.duration_frames;
            active.start_color_keys = route.start_color_keys;
            active.end_color_keys = route.end_color_keys;
            active.emission_keys = route.emission_keys;
            active.speed_keys = route.speed_keys;
            active.life_keys = route.life_keys;
            active.size_keys = route.size_keys;
            active.source_blend_period_seconds =
                route.source_blend_period_seconds;
            active.source_start_delay_seconds =
                static_cast<float>(start_delay);
            active.has_source_filter = route.has_source_filter;
            if (route.has_source_filter) {
                active.source_filter = route.source_filter;
            }
            active.persistent = persistent;
            active_venue_particles_.push_back(std::move(active));
            venue_route_applied = true;
            if (debug_venue) {
                std::fprintf(
                    stderr,
                    "[world] venue event %s: ParticleSys %s via %s start_color_keys=%zu end_color_keys=%zu emit_keys=%zu speed_keys=%zu life_keys=%zu size_keys=%zu frames=%.1f seconds=%.3f blend_period=%.3f wait=%d delay=%.3f inherited_wait=%.3f filter=%s %s\n",
                    event_name.c_str(), route.particle.c_str(),
                    route.anim.c_str(), route.start_color_keys.size(),
                    route.end_color_keys.size(), route.emission_keys.size(),
                    route.speed_keys.size(), route.life_keys.size(),
                    route.size_keys.size(), route.duration_frames,
                    active_venue_particles_.back().duration_seconds,
                    active_venue_particles_.back().source_blend_period_seconds,
                    route.source_wait ? 1 : 0, route_delay, wait_seconds,
                    route.has_source_filter ? route.source_filter.name.c_str()
                                            : "none",
                    persistent ? "persistent" : "transient");
            }
        }
    }
    for (const auto& [material, alpha] : material_changes) {
        const auto mesh_it = venue_material_meshes_.find(material);
        if (mesh_it == venue_material_meshes_.end()) continue;
        if (debug_venue) {
            std::fprintf(stderr,
                         "[world] venue event %s: material %s %s %zu meshes\n",
                         event_name.c_str(), material.c_str(),
                         alpha <= 0.001f ? "hide" : "show",
                         mesh_it->second.size());
        }
    }
    const bool current_visibility_applied =
        apply_venue_event_visibility(event_name, debug_venue);
    if (current_visibility_applied) venue_route_applied = true;
    if (venue_script_object_applied) venue_route_applied = true;
    if (const auto filter_event_it =
            venue_event_anim_filters_.find(event_name);
        filter_event_it != venue_event_anim_filters_.end()) {
        std::vector<VenueAnimFilter> enabled_filters;
        enabled_filters.reserve(filter_event_it->second.size());
        for (const auto& filter : filter_event_it->second) {
            if (venue_event_trigger_enabled_by_name(filter.source_trigger)) {
                enabled_filters.push_back(filter);
            } else if (debug_venue) {
                std::fprintf(
                    stderr,
                    "[world] venue event %s: AnimFilter %s skipped by disabled source trigger %s\n",
                    event_name.c_str(), filter.name.c_str(),
                    filter.source_trigger.c_str());
            }
        }
        if (enabled_filters.empty()) {
            if (debug_venue) {
                std::fprintf(
                    stderr,
                    "[world] venue event %s: all AnimFilters disabled by source trigger gates\n",
                    event_name.c_str());
            }
        } else {
            for (auto& filter : enabled_filters) {
                if (!filter.event_wait) continue;
                double wait_seconds = 0.0;
                for (const auto& active : active_venue_anim_filters_) {
                    if (active.polled) continue;
                    const double active_elapsed =
                        std::max(0.0, song_time_ - active.start_time);
                    for (const auto& active_filter : active.filters) {
                        if (!venue_filters_share_authored_target(
                                active_filter, filter)) {
                            continue;
                        }
                        wait_seconds = std::max(
                            wait_seconds,
                            venue_filter_time_until_end_seconds(
                                active_filter, active_elapsed, &chart_,
                                active.start_time));
                    }
                }
                if (wait_seconds > 0.001) {
                    filter.event_delay_seconds +=
                        static_cast<float>(wait_seconds);
                    if (debug_venue) {
                        std::fprintf(
                            stderr,
                            "[world] venue event %s: AnimFilter %s wait inherited %.3fs from active source task\n",
                            event_name.c_str(), filter.name.c_str(),
                            wait_seconds);
                    }
                }
            }
            ActiveVenueAnimFilter active_filter;
            active_filter.event_name = event_name;
            active_filter.filters = enabled_filters;
            active_filter.start_time = song_time_;
            active_filter.persistent = persistent;
            const size_t replaced_filters = start_source_venue_filter_tasks(
                active_filter, active_venue_anim_filters_);
            if (replaced_filters > 0 && debug_venue) {
                std::ostringstream targets;
                for (const auto& filter : enabled_filters) {
                    if (filter.target_ref.empty()) continue;
                    if (targets.tellp() > 0) targets << ',';
                    targets << filter.target_ref;
                }
                std::fprintf(
                    stderr,
                    "[world] venue event %s: replaced %zu active AnimFilters for target(s) %s\n",
                    event_name.c_str(), replaced_filters,
                    targets.str().c_str());
            }
            active_venue_anim_filters_.push_back(std::move(active_filter));
            venue_route_applied = true;
            if (debug_venue) {
                for (const auto& filter : enabled_filters) {
                    std::fprintf(
                        stderr,
                        "[world] venue event %s: AnimFilter %s target=%s source=%s rate=%d frame %.2f..%.2f targets=%zu mesh_anims=%zu scale=%.3f period=%.3f offset=%.3f type=%d blend=%.3f wait=%d delay=%.3f %s\n",
                        event_name.c_str(), filter.name.c_str(),
                        filter.target_ref.c_str(),
                        filter.source_trigger.c_str(), filter.anim_rate,
                        filter.start_frame, filter.end_frame,
                        filter.targets.size(),
                        filter.mesh_anim_targets.size(), filter.scale,
                        filter.period, filter.offset_frame, filter.type,
                        filter.event_blend_seconds,
                        filter.event_wait ? 1 : 0,
                        filter.event_delay_seconds,
                        persistent ? "persistent" : "transient");
                }
            }
        }
    }
    if (world_) {
        world_->set_material_alpha_multipliers(composed_venue_material_alpha());
        if (material_color_changed)
            world_->set_material_color_overrides(venue_material_colors_);
        if (material_texture_changed)
            world_->set_material_texture_overrides(venue_material_textures_);
        if (material_tex_changed)
            world_->set_material_tex_transform_overrides(
                venue_material_tex_transforms_);
        if (environment_color_changed)
            world_->set_environment_color_overrides(venue_environment_colors_);
        if (environment_fog_changed)
            world_->set_environment_fog_overrides(
                compose_environment_fog_overrides(
                    venue_environment_fog_colors_,
                    venue_environment_fog_ranges_,
                    &venue_environment_fog_enabled_));
        if (light_color_changed)
            world_->set_light_color_overrides(venue_light_colors_);
        if (light_state_changed)
            world_->set_light_state_overrides(venue_light_state_overrides_);
        world_->set_hidden_meshes(composed_venue_hidden_meshes());
    }
    if (lighting_) {
        lighting_->set_material_alpha_multipliers(
            composed_lighting_material_alpha());
    }
    update_active_venue_light_anims();
    update_active_venue_particles();
    update_active_venue_anim_filters();
    const bool lighting_route_applied =
        apply_lighting_event(event_name, persistent);
    if (has_decoded_route_entry && !venue_route_applied &&
        !lighting_route_applied &&
        debug_venue) {
        std::fprintf(stderr,
                     "[world] event %s: no decoded venue/lighting routes\n",
                     event_name.c_str());
    }
    if (next_link_depth >= 16) {
        if (debug_venue) {
            std::fprintf(stderr,
                         "[world] venue event %s: next_link recursion guard\n",
                         event_name.c_str());
        }
        return;
    }
    const auto next_links_it = venue_event_next_links_.find(event_name);
    if (next_links_it == venue_event_next_links_.end()) return;
    for (const auto& linked_event : next_links_it->second) {
        if (linked_event.empty() || linked_event == event_name) continue;
        if (debug_venue) {
            std::fprintf(stderr, "[world] venue event %s: next_link -> %s\n",
                         event_name.c_str(), linked_event.c_str());
        }
        apply_venue_event(linked_event, false, false, next_link_depth + 1);
    }
}

void Gameplay::resend_active_venue_event() {
    if (active_venue_event_.empty()) return;
    const std::string active = active_venue_event_;
    std::fprintf(stderr, "[world] resend_excitement: %s\n", active.c_str());
    apply_venue_event(active, true, true);
}

